import {getDb,sql} from '@cacsms/database';
export async function findUserByEmail(email:string){const db=await getDb();const r=await db.request().input('email',sql.NVarChar(320),email.toLowerCase()).query(`SELECT TOP 1 UserId,Email,DisplayName,PasswordHash,IsActive,LastLoginAt,MfaEnabled FROM dbo.Users WHERE LOWER(Email)=@email`);return r.recordset[0]||null}
export async function listMemberships(userId:string){const db=await getDb();const r=await db.request().input('userId',sql.UniqueIdentifier,userId).query(`SELECT w.WorkspaceId,w.Name,w.Slug,r.Name RoleName,wu.JoinedAt FROM dbo.WorkspaceUsers wu JOIN dbo.Workspaces w ON w.WorkspaceId=wu.WorkspaceId JOIN dbo.Roles r ON r.RoleId=wu.RoleId WHERE wu.UserId=@userId AND w.IsActive=1 ORDER BY w.Name`);return r.recordset}
export async function touchLogin(userId:string){const db=await getDb();await db.request().input('id',sql.UniqueIdentifier,userId).query(`UPDATE dbo.Users SET LastLoginAt=SYSUTCDATETIME(),UpdatedAt=SYSUTCDATETIME() WHERE UserId=@id`)}
export async function listUsers(workspaceId:string){const db=await getDb();const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).query(`SELECT u.UserId,u.Email,u.DisplayName,u.IsActive,u.MfaEnabled,u.LastLoginAt,r.Name RoleName,wu.MembershipStatus,wu.JoinedAt FROM dbo.WorkspaceUsers wu JOIN dbo.Users u ON u.UserId=wu.UserId JOIN dbo.Roles r ON r.RoleId=wu.RoleId WHERE wu.WorkspaceId=@ws ORDER BY u.DisplayName`);return r.recordset}
export async function listRoles(){const db=await getDb();const r=await db.request().query(`SELECT r.RoleId,r.Name,r.Description,r.IsSystemRole,p.PermissionKey,p.DisplayName PermissionName,CASE WHEN rp.RoleId IS NULL THEN 0 ELSE 1 END IsGranted FROM dbo.Roles r CROSS JOIN dbo.Permissions p LEFT JOIN dbo.RolePermissions rp ON rp.RoleId=r.RoleId AND rp.PermissionId=p.PermissionId ORDER BY r.Name,p.PermissionKey`);return r.recordset}
export async function writeAudit(userId:string|null,workspaceId:string|null,action:string,entity:string,meta:string){const db=await getDb();await db.request().input('uid',sql.UniqueIdentifier,userId).input('ws',sql.UniqueIdentifier,workspaceId).input('action',sql.NVarChar(100),action).input('entity',sql.NVarChar(100),entity).input('meta',sql.NVarChar(sql.MAX),meta).query(`INSERT dbo.AuditEvents(UserId,WorkspaceId,Action,EntityType,MetadataJson) VALUES(@uid,@ws,@action,@entity,@meta)`)}

export async function getCommandCenter(workspaceId:string,userId:string){
 const db=await getDb(); const req=db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('uid',sql.UniqueIdentifier,userId);
 const [summary,projects,tasks,notes,agents,schedule,usage]=await Promise.all([
  req.query(`SELECT
   COUNT(*) TotalProjects,
   SUM(CASE WHEN Status='NOT_STARTED' THEN 1 ELSE 0 END) NotStarted,
   SUM(CASE WHEN Status IN('IN_PROGRESS','AWAITING_APPROVAL','PAUSED') THEN 1 ELSE 0 END) Active,
   SUM(CASE WHEN Status='COMPLETED' THEN 1 ELSE 0 END) Completed,
   SUM(CASE WHEN Status IN('BLOCKED','FAILED') THEN 1 ELSE 0 END) Exceptions
   FROM dbo.ContentProjects WHERE WorkspaceId=@ws`),
  db.request().input('ws',sql.UniqueIdentifier,workspaceId).query(`SELECT TOP 12 p.ContentProjectId,p.ContentCode,p.WorkingTitle,p.Status,p.AutonomyMode,p.UpdatedAt,
   ISNULL(x.CompletedStages,0) CompletedStages,ISNULL(x.TotalStages,22) TotalStages,ISNULL(x.ProgressPercent,0) ProgressPercent,
   x.CurrentStageKey,x.CurrentStageName
   FROM dbo.ContentProjects p OUTER APPLY(SELECT COUNT(*) TotalStages,SUM(CASE WHEN pse.Status='COMPLETED' THEN 1 ELSE 0 END) CompletedStages,
    CAST(AVG(CAST(pse.ProgressPercent AS DECIMAL(9,2))) AS DECIMAL(5,2)) ProgressPercent,
    MAX(CASE WHEN pse.Status IN('IN_PROGRESS','AI_PROCESSING','AWAITING_APPROVAL','PAUSED','BLOCKED','FAILED') THEN wsd.StageKey END) CurrentStageKey,
    MAX(CASE WHEN pse.Status IN('IN_PROGRESS','AI_PROCESSING','AWAITING_APPROVAL','PAUSED','BLOCKED','FAILED') THEN wsd.DisplayName END) CurrentStageName
    FROM dbo.ProjectStageExecutions pse JOIN dbo.WorkflowStageDefinitions wsd ON wsd.WorkflowStageDefinitionId=pse.WorkflowStageDefinitionId WHERE pse.ContentProjectId=p.ContentProjectId)x
   WHERE p.WorkspaceId=@ws ORDER BY CASE p.Status WHEN 'IN_PROGRESS' THEN 0 WHEN 'AWAITING_APPROVAL' THEN 1 WHEN 'PAUSED' THEN 2 ELSE 3 END,p.UpdatedAt DESC`),
  db.request().input('uid',sql.UniqueIdentifier,userId).input('ws',sql.UniqueIdentifier,workspaceId).query(`SELECT TOP 8 wi.WorkItemId,wi.Title,wi.Description,wi.WorkType,wi.Priority,wi.Status,wi.StageKey,wi.DueAt,p.ContentCode,p.WorkingTitle FROM dbo.WorkItems wi LEFT JOIN dbo.ContentProjects p ON p.ContentProjectId=wi.ContentProjectId WHERE wi.WorkspaceId=@ws AND (wi.AssignedUserId=@uid OR wi.AssignedUserId IS NULL) AND wi.Status NOT IN('COMPLETED','CANCELLED') ORDER BY CASE wi.Priority WHEN 'URGENT' THEN 0 WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END,wi.DueAt`),
  db.request().input('uid',sql.UniqueIdentifier,userId).input('ws',sql.UniqueIdentifier,workspaceId).query(`SELECT TOP 8 NotificationId,Category,Severity,Title,Message,ActionUrl,IsRead,CreatedAt FROM dbo.Notifications WHERE UserId=@uid AND (WorkspaceId=@ws OR WorkspaceId IS NULL) ORDER BY CreatedAt DESC`),
  db.request().input('ws',sql.UniqueIdentifier,workspaceId).query(`SELECT TOP 12 AgentRunId,AgentKey,AgentName,StageKey,Status,ProgressPercent,Provider,Model,UpdatedAt,p.ContentCode FROM dbo.AgentRuns a LEFT JOIN dbo.ContentProjects p ON p.ContentProjectId=a.ContentProjectId WHERE a.WorkspaceId=@ws ORDER BY CASE a.Status WHEN 'FAILED' THEN 0 WHEN 'RUNNING' THEN 1 WHEN 'WAITING' THEN 2 ELSE 3 END,a.UpdatedAt DESC`),
  db.request().input('ws',sql.UniqueIdentifier,workspaceId).query(`SELECT TOP 8 ps.PublishingScheduleId,ps.Platform,ps.ScheduledAt,ps.Status,p.ContentCode,p.WorkingTitle FROM dbo.PublishingSchedule ps JOIN dbo.ContentProjects p ON p.ContentProjectId=ps.ContentProjectId WHERE ps.WorkspaceId=@ws AND ps.ScheduledAt>=DATEADD(day,-1,SYSUTCDATETIME()) ORDER BY ps.ScheduledAt`),
  db.request().input('ws',sql.UniqueIdentifier,workspaceId).query(`SELECT ISNULL(SUM(CASE WHEN CreatedAt>=CAST(SYSUTCDATETIME() AS date) THEN 1 ELSE 0 END),0) GenerationsToday,ISNULL(SUM(CASE WHEN CreatedAt>=DATEFROMPARTS(YEAR(SYSUTCDATETIME()),MONTH(SYSUTCDATETIME()),1) THEN EstimatedCost ELSE 0 END),0) MonthCost FROM dbo.GenerationUsage WHERE WorkspaceId=@ws`)
 ]);
 return {summary:summary.recordset[0],projects:projects.recordset,tasks:tasks.recordset,notifications:notes.recordset,agents:agents.recordset,schedule:schedule.recordset,usage:usage.recordset[0]};
}
export async function listProjectStages(workspaceId:string,projectId:string){const db=await getDb();const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).query(`SELECT wsd.StageKey,wsd.StageOrder,wsd.DisplayName,wsd.PhaseName,wsd.IsHumanGate,ISNULL(pse.Status,'NOT_STARTED') Status,ISNULL(pse.ProgressPercent,0) ProgressPercent,pse.StartedAt,pse.CompletedAt,pse.PausedAt,pse.LastError FROM dbo.WorkflowStageDefinitions wsd LEFT JOIN dbo.ProjectStageExecutions pse ON pse.WorkflowStageDefinitionId=wsd.WorkflowStageDefinitionId AND pse.ContentProjectId=@pid WHERE wsd.IsActive=1 AND EXISTS(SELECT 1 FROM dbo.ContentProjects p WHERE p.ContentProjectId=@pid AND p.WorkspaceId=@ws) ORDER BY wsd.StageOrder`);return r.recordset}
export async function controlProject(workspaceId:string,projectId:string,userId:string,action:'START'|'PAUSE'|'RESUME'|'STOP'|'RESTART',reason?:string){const db=await getDb();const tx=new sql.Transaction(db);await tx.begin();try{const q=new sql.Request(tx).input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).query(`SELECT Status FROM dbo.ContentProjects WITH(UPDLOCK,ROWLOCK) WHERE ContentProjectId=@pid AND WorkspaceId=@ws`);const current=(await q).recordset[0]?.Status;if(!current)throw Object.assign(new Error('Project not found'),{statusCode:404});const allowed:any={START:['NOT_STARTED'],PAUSE:['IN_PROGRESS'],RESUME:['PAUSED'],STOP:['IN_PROGRESS','PAUSED','AWAITING_APPROVAL','BLOCKED','FAILED'],RESTART:['COMPLETED','FAILED','BLOCKED']};if(!allowed[action].includes(current))throw Object.assign(new Error(`${action} is not valid while project is ${current}`),{statusCode:409});const next=action==='PAUSE'?'PAUSED':action==='STOP'?'NOT_STARTED':'IN_PROGRESS';await new sql.Request(tx).input('pid',sql.UniqueIdentifier,projectId).input('next',sql.NVarChar(30),next).query(`UPDATE dbo.ContentProjects SET Status=@next,UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid`);if(action==='START'||action==='RESTART'){await new sql.Request(tx).input('pid',sql.UniqueIdentifier,projectId).query(`INSERT dbo.ProjectStageExecutions(ContentProjectId,WorkflowStageDefinitionId,Status,ProgressPercent) SELECT @pid,WorkflowStageDefinitionId,CASE WHEN StageOrder=1 THEN 'IN_PROGRESS' ELSE 'NOT_STARTED' END,0 FROM dbo.WorkflowStageDefinitions d WHERE d.IsActive=1 AND NOT EXISTS(SELECT 1 FROM dbo.ProjectStageExecutions e WHERE e.ContentProjectId=@pid AND e.WorkflowStageDefinitionId=d.WorkflowStageDefinitionId)`)}if(action==='PAUSE')await new sql.Request(tx).input('pid',sql.UniqueIdentifier,projectId).query(`UPDATE dbo.ProjectStageExecutions SET Status='PAUSED',PausedAt=SYSUTCDATETIME(),UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND Status IN('IN_PROGRESS','AI_PROCESSING')`);if(action==='RESUME')await new sql.Request(tx).input('pid',sql.UniqueIdentifier,projectId).query(`UPDATE dbo.ProjectStageExecutions SET Status='IN_PROGRESS',PausedAt=NULL,UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND Status='PAUSED'`);if(action==='STOP')await new sql.Request(tx).input('pid',sql.UniqueIdentifier,projectId).query(`UPDATE dbo.ProjectStageExecutions SET Status=CASE WHEN Status='COMPLETED' THEN Status ELSE 'NOT_STARTED' END,ProgressPercent=CASE WHEN Status='COMPLETED' THEN 100 ELSE 0 END,StartedAt=CASE WHEN Status='COMPLETED' THEN StartedAt ELSE NULL END,PausedAt=NULL,UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid`);await new sql.Request(tx).input('pid',sql.UniqueIdentifier,projectId).input('action',sql.NVarChar(30),action).input('prev',sql.NVarChar(30),current).input('next',sql.NVarChar(30),next).input('reason',sql.NVarChar(1000),reason||null).input('uid',sql.UniqueIdentifier,userId).query(`INSERT dbo.ProjectControlEvents(ContentProjectId,Action,PreviousStatus,NewStatus,Reason,PerformedByUserId) VALUES(@pid,@action,@prev,@next,@reason,@uid)`);await tx.commit();return {projectId,previousStatus:current,status:next,action}}catch(e){await tx.rollback();throw e}}
export async function listMyWork(workspaceId:string,userId:string){const db=await getDb();const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('uid',sql.UniqueIdentifier,userId).query(`SELECT wi.WorkItemId,wi.Title,wi.Description,wi.WorkType,wi.Priority,wi.Status,wi.StageKey,wi.DueAt,wi.CreatedAt,p.ContentProjectId,p.ContentCode,p.WorkingTitle FROM dbo.WorkItems wi LEFT JOIN dbo.ContentProjects p ON p.ContentProjectId=wi.ContentProjectId WHERE wi.WorkspaceId=@ws AND (wi.AssignedUserId=@uid OR wi.AssignedUserId IS NULL) ORDER BY CASE wi.Status WHEN 'IN_PROGRESS' THEN 0 WHEN 'OPEN' THEN 1 WHEN 'WAITING' THEN 2 ELSE 3 END,CASE wi.Priority WHEN 'URGENT' THEN 0 WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END,wi.DueAt`);return r.recordset}
export async function updateWorkItem(workspaceId:string,userId:string,workItemId:string,status:string){const db=await getDb();const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('uid',sql.UniqueIdentifier,userId).input('id',sql.UniqueIdentifier,workItemId).input('status',sql.NVarChar(30),status).query(`UPDATE dbo.WorkItems SET Status=@status,CompletedAt=CASE WHEN @status='COMPLETED' THEN SYSUTCDATETIME() ELSE NULL END,UpdatedAt=SYSUTCDATETIME() OUTPUT inserted.* WHERE WorkItemId=@id AND WorkspaceId=@ws AND (AssignedUserId=@uid OR AssignedUserId IS NULL)`);return r.recordset[0]||null}
export async function listNotifications(workspaceId:string,userId:string){const db=await getDb();const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('uid',sql.UniqueIdentifier,userId).query(`SELECT NotificationId,Category,Severity,Title,Message,ActionUrl,IsRead,ReadAt,CreatedAt FROM dbo.Notifications WHERE UserId=@uid AND (WorkspaceId=@ws OR WorkspaceId IS NULL) ORDER BY CreatedAt DESC`);return r.recordset}
export async function markNotification(userId:string,id:string,read:boolean){const db=await getDb();const r=await db.request().input('uid',sql.UniqueIdentifier,userId).input('id',sql.UniqueIdentifier,id).input('read',sql.Bit,read).query(`UPDATE dbo.Notifications SET IsRead=@read,ReadAt=CASE WHEN @read=1 THEN SYSUTCDATETIME() ELSE NULL END OUTPUT inserted.* WHERE NotificationId=@id AND UserId=@uid`);return r.recordset[0]||null}

export type CreateProjectInput={
 workingTitle:string;description?:string;contentType:string;primaryPlatform:string;targetAudience:string;targetCountries:string[];language:string;plannedDurationSeconds?:number;aspectRatio:string;category:string;objective:string;priority:string;deadlineAt?:string;budgetLimit?:number;creativeDirection?:string;autonomyMode:string;distributionTargets?:Array<{platform:string;contentFormat:string;isPrimary?:boolean;aspectRatio?:string;targetDurationSeconds?:number}>;
};
export async function listContentProjects(workspaceId:string,opts:{search?:string;status?:string;platform?:string;priority?:string;limit?:number;offset?:number}={}){
 const db=await getDb();const limit=Math.min(Math.max(opts.limit||50,1),200),offset=Math.max(opts.offset||0,0);
 const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('search',sql.NVarChar(300),opts.search?`%${opts.search}%`:null).input('status',sql.NVarChar(30),opts.status||null).input('platform',sql.NVarChar(50),opts.platform||null).input('priority',sql.NVarChar(20),opts.priority||null).input('limit',sql.Int,limit).input('offset',sql.Int,offset).query(`
 SELECT p.ContentProjectId,p.ContentCode,p.WorkingTitle,p.Description,p.Status,p.AutonomyMode,p.PrimaryPlatform,p.ContentType,p.Category,p.Objective,p.Priority,p.DeadlineAt,p.BudgetLimit,p.Language,p.AspectRatio,p.PlannedDurationSeconds,p.CreativeDirection,p.TargetAudience,p.TargetCountriesJson,p.CreatedAt,p.UpdatedAt,u.DisplayName OwnerName,
 ISNULL(x.TotalStages,22) TotalStages,ISNULL(x.CompletedStages,0) CompletedStages,ISNULL(x.ProgressPercent,0) ProgressPercent,x.CurrentStageKey,x.CurrentStageName,
 COUNT(1) OVER() TotalRows
 FROM dbo.ContentProjects p LEFT JOIN dbo.Users u ON u.UserId=p.OwnerUserId
 OUTER APPLY(SELECT COUNT(*) TotalStages,SUM(CASE WHEN e.Status='COMPLETED' THEN 1 ELSE 0 END) CompletedStages,CAST(AVG(CAST(CASE WHEN e.Status='COMPLETED' THEN 100 ELSE ISNULL(e.ProgressPercent,0) END AS DECIMAL(8,2))) AS INT) ProgressPercent,
  MAX(CASE WHEN e.Status IN('IN_PROGRESS','AI_PROCESSING','AWAITING_APPROVAL','PAUSED','BLOCKED','FAILED') THEN d.StageKey END) CurrentStageKey,
  MAX(CASE WHEN e.Status IN('IN_PROGRESS','AI_PROCESSING','AWAITING_APPROVAL','PAUSED','BLOCKED','FAILED') THEN d.DisplayName END) CurrentStageName
  FROM dbo.ProjectStageExecutions e JOIN dbo.WorkflowStageDefinitions d ON d.WorkflowStageDefinitionId=e.WorkflowStageDefinitionId WHERE e.ContentProjectId=p.ContentProjectId) x
 WHERE p.WorkspaceId=@ws AND p.ArchivedAt IS NULL
 AND (@search IS NULL OR p.ContentCode LIKE @search OR p.WorkingTitle LIKE @search OR p.Description LIKE @search)
 AND (@status IS NULL OR p.Status=@status) AND (@platform IS NULL OR p.PrimaryPlatform=@platform) AND (@priority IS NULL OR p.Priority=@priority)
 ORDER BY CASE p.Priority WHEN 'URGENT' THEN 0 WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END,p.UpdatedAt DESC OFFSET @offset ROWS FETCH NEXT @limit ROWS ONLY`);
 return {items:r.recordset,total:Number(r.recordset[0]?.TotalRows||0),limit,offset};
}
export async function createContentProject(workspaceId:string,userId:string,input:CreateProjectInput){
 const db=await getDb();const tx=new sql.Transaction(db);await tx.begin();try{
  const year=new Date().getUTCFullYear();const seq=await new sql.Request(tx).input('ws',sql.UniqueIdentifier,workspaceId).input('prefix',sql.NVarChar(20),`CAC-${year}-%`).query(`SELECT ISNULL(MAX(TRY_CAST(RIGHT(ContentCode,6) AS INT)),0)+1 NextNo FROM dbo.ContentProjects WITH(UPDLOCK,HOLDLOCK) WHERE WorkspaceId=@ws AND ContentCode LIKE @prefix`);const code=`CAC-${year}-${String(seq.recordset[0].NextNo).padStart(6,'0')}`;
  const q=await new sql.Request(tx).input('ws',sql.UniqueIdentifier,workspaceId).input('code',sql.NVarChar(30),code).input('title',sql.NVarChar(250),input.workingTitle).input('desc',sql.NVarChar(1500),input.description||null).input('type',sql.NVarChar(50),input.contentType).input('platform',sql.NVarChar(50),input.primaryPlatform).input('audience',sql.NVarChar(500),input.targetAudience).input('countries',sql.NVarChar(sql.MAX),JSON.stringify(input.targetCountries||[])).input('language',sql.NVarChar(50),input.language).input('duration',sql.Int,input.plannedDurationSeconds||null).input('ratio',sql.NVarChar(20),input.aspectRatio).input('category',sql.NVarChar(100),input.category).input('objective',sql.NVarChar(100),input.objective).input('priority',sql.NVarChar(20),input.priority).input('deadline',sql.DateTime2,input.deadlineAt?new Date(input.deadlineAt):null).input('budget',sql.Decimal(18,2),input.budgetLimit??null).input('creative',sql.NVarChar(100),input.creativeDirection||null).input('mode',sql.NVarChar(30),input.autonomyMode).input('uid',sql.UniqueIdentifier,userId).query(`INSERT dbo.ContentProjects(WorkspaceId,ContentCode,WorkingTitle,Description,Status,AutonomyMode,OwnerUserId,CreatedByUserId,ContentType,PrimaryPlatform,TargetAudience,TargetCountriesJson,Language,PlannedDurationSeconds,AspectRatio,Category,Objective,Priority,DeadlineAt,BudgetLimit,CreativeDirection) OUTPUT inserted.* VALUES(@ws,@code,@title,@desc,'NOT_STARTED',@mode,@uid,@uid,@type,@platform,@audience,@countries,@language,@duration,@ratio,@category,@objective,@priority,@deadline,@budget,@creative)`);
  const project=q.recordset[0];
  await new sql.Request(tx).input('pid',sql.UniqueIdentifier,project.ContentProjectId).query(`INSERT dbo.ProjectStageExecutions(ContentProjectId,WorkflowStageDefinitionId,Status,ProgressPercent) SELECT @pid,WorkflowStageDefinitionId,'NOT_STARTED',0 FROM dbo.WorkflowStageDefinitions WHERE IsActive=1`);
  const targets=input.distributionTargets?.length?input.distributionTargets:[{platform:input.primaryPlatform,contentFormat:input.contentType,isPrimary:true,aspectRatio:input.aspectRatio,targetDurationSeconds:input.plannedDurationSeconds}];
  for(const t of targets)await new sql.Request(tx).input('pid',sql.UniqueIdentifier,project.ContentProjectId).input('platform',sql.NVarChar(50),t.platform).input('format',sql.NVarChar(50),t.contentFormat).input('primary',sql.Bit,!!t.isPrimary).input('ratio',sql.NVarChar(20),t.aspectRatio||null).input('duration',sql.Int,t.targetDurationSeconds||null).query(`INSERT dbo.ProjectDistributionTargets(ContentProjectId,Platform,ContentFormat,IsPrimary,AspectRatio,TargetDurationSeconds) VALUES(@pid,@platform,@format,@primary,@ratio,@duration)`);
  const snapshot=JSON.stringify({workingTitle:input.workingTitle,description:input.description||'',contentType:input.contentType,primaryPlatform:input.primaryPlatform,targetAudience:input.targetAudience,targetCountries:input.targetCountries,language:input.language,plannedDurationSeconds:input.plannedDurationSeconds,aspectRatio:input.aspectRatio,category:input.category,objective:input.objective,priority:input.priority,deadlineAt:input.deadlineAt,budgetLimit:input.budgetLimit,creativeDirection:input.creativeDirection,autonomyMode:input.autonomyMode});
  await new sql.Request(tx).input('pid',sql.UniqueIdentifier,project.ContentProjectId).input('snap',sql.NVarChar(sql.MAX),snapshot).input('uid',sql.UniqueIdentifier,userId).query(`INSERT dbo.ProjectVersions(ContentProjectId,VersionType,VersionNumber,SourceStageKey,Title,SnapshotJson,ChangeSummary,CreatedByUserId) VALUES(@pid,'PROJECT_SNAPSHOT',1,'PROJECT_INITIATION','Project created',@snap,'Initial project configuration',@uid)`);
  await new sql.Request(tx).input('pid',sql.UniqueIdentifier,project.ContentProjectId).input('uid',sql.UniqueIdentifier,userId).input('code',sql.NVarChar(30),code).query(`INSERT dbo.ProjectActivities(ContentProjectId,ActivityType,Title,Details,ActorType,ActorUserId) VALUES(@pid,'PROJECT_CREATED','Project created','Master content project '+@code+' created and initialized with the 22-stage workflow.','HUMAN',@uid)`);
  await tx.commit();return project;
 }catch(e){await tx.rollback();throw e}
}
export async function getContentProject(workspaceId:string,projectId:string){const db=await getDb();const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).query(`SELECT p.*,u.DisplayName OwnerName,cu.DisplayName CreatedByName FROM dbo.ContentProjects p LEFT JOIN dbo.Users u ON u.UserId=p.OwnerUserId LEFT JOIN dbo.Users cu ON cu.UserId=p.CreatedByUserId WHERE p.ContentProjectId=@pid AND p.WorkspaceId=@ws AND p.ArchivedAt IS NULL; SELECT Platform,ContentFormat,IsPrimary,AspectRatio,TargetDurationSeconds,Status FROM dbo.ProjectDistributionTargets WHERE ContentProjectId=@pid ORDER BY IsPrimary DESC,Platform; SELECT pc.ProjectRole,u.UserId,u.DisplayName,u.Email FROM dbo.ProjectCollaborators pc JOIN dbo.Users u ON u.UserId=pc.UserId WHERE pc.ContentProjectId=@pid`);if(!(r.recordsets as any)[0][0])return null;return {project:(r.recordsets as any)[0][0],distribution:(r.recordsets as any)[1],collaborators:(r.recordsets as any)[2]}}
export async function updateContentProject(workspaceId:string,projectId:string,userId:string,input:Partial<CreateProjectInput>){const db=await getDb();const current=await getContentProject(workspaceId,projectId);if(!current)return null;const p=current.project;const value=(k:string,fallback:any)=>(input as any)[k]!==undefined?(input as any)[k]:fallback;const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).input('title',sql.NVarChar(250),value('workingTitle',p.WorkingTitle)).input('desc',sql.NVarChar(1500),value('description',p.Description)).input('audience',sql.NVarChar(500),value('targetAudience',p.TargetAudience)).input('countries',sql.NVarChar(sql.MAX),JSON.stringify(value('targetCountries',JSON.parse(p.TargetCountriesJson||'[]')))).input('language',sql.NVarChar(50),value('language',p.Language)).input('duration',sql.Int,value('plannedDurationSeconds',p.PlannedDurationSeconds)).input('ratio',sql.NVarChar(20),value('aspectRatio',p.AspectRatio)).input('category',sql.NVarChar(100),value('category',p.Category)).input('objective',sql.NVarChar(100),value('objective',p.Objective)).input('priority',sql.NVarChar(20),value('priority',p.Priority)).input('deadline',sql.DateTime2,value('deadlineAt',p.DeadlineAt)?new Date(value('deadlineAt',p.DeadlineAt)):null).input('budget',sql.Decimal(18,2),value('budgetLimit',p.BudgetLimit)).input('creative',sql.NVarChar(100),value('creativeDirection',p.CreativeDirection)).input('mode',sql.NVarChar(30),value('autonomyMode',p.AutonomyMode)).input('type',sql.NVarChar(50),value('contentType',p.ContentType)).input('platform',sql.NVarChar(50),value('primaryPlatform',p.PrimaryPlatform)).query(`UPDATE dbo.ContentProjects SET WorkingTitle=@title,Description=@desc,TargetAudience=@audience,TargetCountriesJson=@countries,Language=@language,PlannedDurationSeconds=@duration,AspectRatio=@ratio,Category=@category,Objective=@objective,Priority=@priority,DeadlineAt=@deadline,BudgetLimit=@budget,CreativeDirection=@creative,AutonomyMode=@mode,ContentType=@type,PrimaryPlatform=@platform,UpdatedAt=SYSUTCDATETIME() OUTPUT inserted.* WHERE ContentProjectId=@pid AND WorkspaceId=@ws`);await db.request().input('pid',sql.UniqueIdentifier,projectId).input('uid',sql.UniqueIdentifier,userId).query(`INSERT dbo.ProjectActivities(ContentProjectId,ActivityType,Title,Details,ActorType,ActorUserId) VALUES(@pid,'PROJECT_UPDATED','Project details updated','Project metadata and production configuration were updated.','HUMAN',@uid)`);return r.recordset[0]||null}
export async function listProjectAssets(workspaceId:string,projectId:string){const db=await getDb();const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).query(`SELECT a.ProjectAssetId,a.AssetType,a.FileName,a.StageKey,a.StorageUrl,a.MimeType,a.FileSizeBytes,a.VersionNumber,a.IsMaster,a.Status,a.CreatedAt,u.DisplayName CreatedBy FROM dbo.ProjectAssets a LEFT JOIN dbo.Users u ON u.UserId=a.CreatedByUserId WHERE a.ContentProjectId=@pid AND EXISTS(SELECT 1 FROM dbo.ContentProjects p WHERE p.ContentProjectId=@pid AND p.WorkspaceId=@ws) ORDER BY a.CreatedAt DESC`);return r.recordset}
export async function listProjectVersions(workspaceId:string,projectId:string){const db=await getDb();const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).query(`SELECT v.ProjectVersionId,v.VersionType,v.VersionNumber,v.SourceStageKey,v.Title,v.ChangeSummary,v.IsApproved,v.CreatedAt,u.DisplayName CreatedBy FROM dbo.ProjectVersions v LEFT JOIN dbo.Users u ON u.UserId=v.CreatedByUserId WHERE v.ContentProjectId=@pid AND EXISTS(SELECT 1 FROM dbo.ContentProjects p WHERE p.ContentProjectId=@pid AND p.WorkspaceId=@ws) ORDER BY v.CreatedAt DESC`);return r.recordset}
export async function listProjectApprovals(workspaceId:string,projectId:string){const db=await getDb();const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).query(`SELECT a.ProjectApprovalId,a.StageKey,a.ApprovalType,a.Status,a.RequestNote,a.DecisionComment,a.RequestedAt,a.DecidedAt,ass.DisplayName AssignedTo,dec.DisplayName DecisionBy FROM dbo.ProjectApprovals a LEFT JOIN dbo.Users ass ON ass.UserId=a.AssignedToUserId LEFT JOIN dbo.Users dec ON dec.UserId=a.DecisionByUserId WHERE a.ContentProjectId=@pid AND EXISTS(SELECT 1 FROM dbo.ContentProjects p WHERE p.ContentProjectId=@pid AND p.WorkspaceId=@ws) ORDER BY a.RequestedAt DESC`);return r.recordset}
export async function listProjectActivities(workspaceId:string,projectId:string){const db=await getDb();const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).query(`SELECT a.ProjectActivityId,a.ActivityType,a.StageKey,a.Title,a.Details,a.ActorType,a.AgentName,a.CreatedAt,u.DisplayName ActorName FROM dbo.ProjectActivities a LEFT JOIN dbo.Users u ON u.UserId=a.ActorUserId WHERE a.ContentProjectId=@pid AND EXISTS(SELECT 1 FROM dbo.ContentProjects p WHERE p.ContentProjectId=@pid AND p.WorkspaceId=@ws) ORDER BY a.CreatedAt DESC`);return r.recordset}
export async function listProjectHandoffs(workspaceId:string,projectId:string){const db=await getDb();const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).query(`SELECT h.ProjectHandoffId,h.FromStageKey,h.ToStageKey,h.OutputType,h.OutputReference,h.Status,h.CreatedAt,h.ConsumedAt,v.VersionType,v.VersionNumber FROM dbo.ProjectHandoffs h LEFT JOIN dbo.ProjectVersions v ON v.ProjectVersionId=h.ProjectVersionId WHERE h.ContentProjectId=@pid AND EXISTS(SELECT 1 FROM dbo.ContentProjects p WHERE p.ContentProjectId=@pid AND p.WorkspaceId=@ws) ORDER BY h.CreatedAt`);return r.recordset}
export async function archiveContentProject(workspaceId:string,projectId:string,userId:string){const db=await getDb();const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).query(`UPDATE dbo.ContentProjects SET ArchivedAt=SYSUTCDATETIME(),UpdatedAt=SYSUTCDATETIME() OUTPUT inserted.ContentProjectId,inserted.ContentCode WHERE ContentProjectId=@pid AND WorkspaceId=@ws AND ArchivedAt IS NULL`);if(r.recordset[0])await db.request().input('pid',sql.UniqueIdentifier,projectId).input('uid',sql.UniqueIdentifier,userId).query(`INSERT dbo.ProjectActivities(ContentProjectId,ActivityType,Title,Details,ActorType,ActorUserId) VALUES(@pid,'PROJECT_ARCHIVED','Project archived','Project removed from active project lists.','HUMAN',@uid)`);return r.recordset[0]||null}

type BriefInput={primaryObjective?:string;secondaryObjectives?:string[];audienceSummary?:string;audienceAgeRange?:string;audienceKnowledgeLevel?:string;audienceInterests?:string[];targetCountries?:string[];distributionPlatforms?:string[];creativeDirection?:string;storyApproach?:string;voiceStyle?:string;visualStyle?:string;desiredDurationSeconds?:number;aspectRatio?:string;language?:string;callToAction?:string;monetizationObjective?:string;contentRestrictions?:string;requiredElements?:string;avoidElements?:string;referenceCreators?:string;researchFocus?:string;successDefinition?:string;notes?:string;changeSummary?:string;audienceSegments?:Array<{segmentName:string;description?:string;ageRange?:string;markets?:string[];interests?:string[];needs?:string[];priorityOrder?:number}>;platformStrategies?:Array<{platform:string;contentFormat:string;isPrimary?:boolean;targetDurationSeconds?:number;aspectRatio?:string;platformGoal?:string;packagingNotes?:string}>;references?:Array<{referenceType:string;title:string;url?:string;notes?:string;isRequired?:boolean}>;successMetrics?:Array<{metricKey:string;displayName:string;targetValue?:number;targetUnit?:string;priorityOrder?:number;notes?:string}>};
const safeJson=(v:any,fb:any=[])=>{try{return typeof v==='string'?JSON.parse(v):v??fb}catch{return fb}};
export async function listStrategyBriefs(workspaceId:string){const db=await getDb();const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).query(`SELECT p.ContentProjectId,p.ContentCode,p.WorkingTitle,p.Status ProjectStatus,p.PrimaryPlatform,p.Priority,p.UpdatedAt ProjectUpdatedAt,b.ContentBriefId,b.CurrentVersionNumber,b.Status BriefStatus,b.PrimaryObjective,b.CreativeDirection,b.ApprovedAt,b.UpdatedAt BriefUpdatedAt,u.DisplayName ApprovedBy FROM dbo.ContentProjects p LEFT JOIN dbo.ContentBriefs b ON b.ContentProjectId=p.ContentProjectId LEFT JOIN dbo.Users u ON u.UserId=b.ApprovedByUserId WHERE p.WorkspaceId=@ws AND p.ArchivedAt IS NULL ORDER BY CASE WHEN b.ContentBriefId IS NULL THEN 0 WHEN b.Status='RETURNED' THEN 1 WHEN b.Status='IN_REVIEW' THEN 2 WHEN b.Status='DRAFT' THEN 3 ELSE 4 END,p.UpdatedAt DESC`);return r.recordset}
export async function getStrategyBrief(workspaceId:string,projectId:string){const db=await getDb();const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).query(`SELECT p.ContentProjectId,p.ContentCode,p.WorkingTitle,p.Description,p.ContentType,p.PrimaryPlatform,p.TargetAudience,p.TargetCountriesJson ProjectTargetCountriesJson,p.Language ProjectLanguage,p.PlannedDurationSeconds,p.AspectRatio ProjectAspectRatio,p.Category,p.Objective ProjectObjective,p.Priority,p.DeadlineAt,p.BudgetLimit,p.CreativeDirection ProjectCreativeDirection,p.AutonomyMode,p.Status ProjectStatus,b.*,au.DisplayName ApprovedBy,cu.DisplayName BriefCreatedBy FROM dbo.ContentProjects p LEFT JOIN dbo.ContentBriefs b ON b.ContentProjectId=p.ContentProjectId LEFT JOIN dbo.Users au ON au.UserId=b.ApprovedByUserId LEFT JOIN dbo.Users cu ON cu.UserId=b.CreatedByUserId WHERE p.ContentProjectId=@pid AND p.WorkspaceId=@ws AND p.ArchivedAt IS NULL; SELECT s.* FROM dbo.ContentBriefAudienceSegments s JOIN dbo.ContentBriefs b ON b.ContentBriefId=s.ContentBriefId WHERE b.ContentProjectId=@pid ORDER BY s.PriorityOrder,s.SegmentName; SELECT ps.* FROM dbo.ContentBriefPlatformStrategies ps JOIN dbo.ContentBriefs b ON b.ContentBriefId=ps.ContentBriefId WHERE b.ContentProjectId=@pid ORDER BY ps.IsPrimary DESC,ps.Platform; SELECT br.* FROM dbo.ContentBriefReferences br JOIN dbo.ContentBriefs b ON b.ContentBriefId=br.ContentBriefId WHERE b.ContentProjectId=@pid ORDER BY br.IsRequired DESC,br.CreatedAt; SELECT sm.* FROM dbo.ContentBriefSuccessMetrics sm JOIN dbo.ContentBriefs b ON b.ContentBriefId=sm.ContentBriefId WHERE b.ContentProjectId=@pid ORDER BY sm.PriorityOrder,sm.DisplayName; SELECT v.ContentBriefVersionId,v.VersionNumber,v.Status,v.ChangeSummary,v.ReviewComment,v.CreatedAt,v.ReviewedAt,cu.DisplayName CreatedBy,ru.DisplayName ReviewedBy FROM dbo.ContentBriefVersions v JOIN dbo.ContentBriefs b ON b.ContentBriefId=v.ContentBriefId LEFT JOIN dbo.Users cu ON cu.UserId=v.CreatedByUserId LEFT JOIN dbo.Users ru ON ru.UserId=v.ReviewedByUserId WHERE b.ContentProjectId=@pid ORDER BY v.VersionNumber DESC`);if(!(r.recordsets as any)[0][0])return null;return {brief:(r.recordsets as any)[0][0],audienceSegments:(r.recordsets as any)[1],platformStrategies:(r.recordsets as any)[2],references:(r.recordsets as any)[3],successMetrics:(r.recordsets as any)[4],versions:(r.recordsets as any)[5]}}
export async function saveStrategyBrief(workspaceId:string,projectId:string,userId:string,input:BriefInput){const db=await getDb();const tx=new sql.Transaction(db);await tx.begin();try{const project=(await new sql.Request(tx).input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).query(`SELECT * FROM dbo.ContentProjects WITH(UPDLOCK) WHERE ContentProjectId=@pid AND WorkspaceId=@ws AND ArchivedAt IS NULL`)).recordset[0];if(!project)throw Object.assign(new Error('Project not found'),{statusCode:404});let brief=(await new sql.Request(tx).input('pid',sql.UniqueIdentifier,projectId).query(`SELECT * FROM dbo.ContentBriefs WITH(UPDLOCK) WHERE ContentProjectId=@pid`)).recordset[0];const existing=(key:string,fb:any=null)=>brief?.[key]??fb;const val=(key:keyof BriefInput,fb:any)=>input[key]!==undefined?input[key]:fb;const countries=val('targetCountries',safeJson(existing('TargetCountriesJson'),safeJson(project.TargetCountriesJson)));const platforms=val('distributionPlatforms',safeJson(existing('DistributionPlatformsJson'),[project.PrimaryPlatform].filter(Boolean)));if(!brief){brief=(await new sql.Request(tx).input('pid',sql.UniqueIdentifier,projectId).input('uid',sql.UniqueIdentifier,userId).query(`INSERT dbo.ContentBriefs(ContentProjectId,CreatedByUserId) OUTPUT inserted.* VALUES(@pid,@uid)`)).recordset[0]}
 const q=new sql.Request(tx).input('bid',sql.UniqueIdentifier,brief.ContentBriefId).input('objective',sql.NVarChar(120),val('primaryObjective',existing('PrimaryObjective',project.Objective))).input('secondary',sql.NVarChar(sql.MAX),JSON.stringify(val('secondaryObjectives',safeJson(existing('SecondaryObjectivesJson'))))).input('audience',sql.NVarChar(1200),val('audienceSummary',existing('AudienceSummary',project.TargetAudience))).input('age',sql.NVarChar(60),val('audienceAgeRange',existing('AudienceAgeRange'))).input('knowledge',sql.NVarChar(80),val('audienceKnowledgeLevel',existing('AudienceKnowledgeLevel'))).input('interests',sql.NVarChar(sql.MAX),JSON.stringify(val('audienceInterests',safeJson(existing('AudienceInterestsJson'))))).input('countries',sql.NVarChar(sql.MAX),JSON.stringify(countries)).input('platforms',sql.NVarChar(sql.MAX),JSON.stringify(platforms)).input('creative',sql.NVarChar(120),val('creativeDirection',existing('CreativeDirection',project.CreativeDirection))).input('story',sql.NVarChar(120),val('storyApproach',existing('StoryApproach'))).input('voice',sql.NVarChar(250),val('voiceStyle',existing('VoiceStyle'))).input('visual',sql.NVarChar(500),val('visualStyle',existing('VisualStyle'))).input('duration',sql.Int,val('desiredDurationSeconds',existing('DesiredDurationSeconds',project.PlannedDurationSeconds))).input('ratio',sql.NVarChar(20),val('aspectRatio',existing('AspectRatio',project.AspectRatio))).input('language',sql.NVarChar(50),val('language',existing('Language',project.Language))).input('cta',sql.NVarChar(1000),val('callToAction',existing('CallToAction'))).input('money',sql.NVarChar(500),val('monetizationObjective',existing('MonetizationObjective'))).input('restrictions',sql.NVarChar(2000),val('contentRestrictions',existing('ContentRestrictions'))).input('required',sql.NVarChar(2000),val('requiredElements',existing('RequiredElements'))).input('avoid',sql.NVarChar(2000),val('avoidElements',existing('AvoidElements'))).input('creators',sql.NVarChar(1000),val('referenceCreators',existing('ReferenceCreators'))).input('research',sql.NVarChar(2000),val('researchFocus',existing('ResearchFocus'))).input('success',sql.NVarChar(2000),val('successDefinition',existing('SuccessDefinition'))).input('notes',sql.NVarChar(2000),val('notes',existing('Notes')));await q.query(`UPDATE dbo.ContentBriefs SET Status='DRAFT',PrimaryObjective=@objective,SecondaryObjectivesJson=@secondary,AudienceSummary=@audience,AudienceAgeRange=@age,AudienceKnowledgeLevel=@knowledge,AudienceInterestsJson=@interests,TargetCountriesJson=@countries,DistributionPlatformsJson=@platforms,CreativeDirection=@creative,StoryApproach=@story,VoiceStyle=@voice,VisualStyle=@visual,DesiredDurationSeconds=@duration,AspectRatio=@ratio,Language=@language,CallToAction=@cta,MonetizationObjective=@money,ContentRestrictions=@restrictions,RequiredElements=@required,AvoidElements=@avoid,ReferenceCreators=@creators,ResearchFocus=@research,SuccessDefinition=@success,Notes=@notes,UpdatedAt=SYSUTCDATETIME() WHERE ContentBriefId=@bid`);
 const replace=async(table:string)=>new sql.Request(tx).input('bid',sql.UniqueIdentifier,brief.ContentBriefId).query(`DELETE FROM dbo.${table} WHERE ContentBriefId=@bid`);if(input.audienceSegments){await replace('ContentBriefAudienceSegments');for(const s of input.audienceSegments)await new sql.Request(tx).input('bid',sql.UniqueIdentifier,brief.ContentBriefId).input('name',sql.NVarChar(150),s.segmentName).input('desc',sql.NVarChar(1000),s.description||null).input('age',sql.NVarChar(60),s.ageRange||null).input('markets',sql.NVarChar(sql.MAX),JSON.stringify(s.markets||[])).input('interests',sql.NVarChar(sql.MAX),JSON.stringify(s.interests||[])).input('needs',sql.NVarChar(sql.MAX),JSON.stringify(s.needs||[])).input('ord',sql.Int,s.priorityOrder||1).query(`INSERT dbo.ContentBriefAudienceSegments(ContentBriefId,SegmentName,Description,AgeRange,MarketsJson,InterestsJson,NeedsJson,PriorityOrder) VALUES(@bid,@name,@desc,@age,@markets,@interests,@needs,@ord)`)}if(input.platformStrategies){await replace('ContentBriefPlatformStrategies');for(const p of input.platformStrategies)await new sql.Request(tx).input('bid',sql.UniqueIdentifier,brief.ContentBriefId).input('platform',sql.NVarChar(60),p.platform).input('format',sql.NVarChar(80),p.contentFormat).input('primary',sql.Bit,!!p.isPrimary).input('duration',sql.Int,p.targetDurationSeconds||null).input('ratio',sql.NVarChar(20),p.aspectRatio||null).input('goal',sql.NVarChar(500),p.platformGoal||null).input('notes',sql.NVarChar(1000),p.packagingNotes||null).query(`INSERT dbo.ContentBriefPlatformStrategies(ContentBriefId,Platform,ContentFormat,IsPrimary,TargetDurationSeconds,AspectRatio,PlatformGoal,PackagingNotes) VALUES(@bid,@platform,@format,@primary,@duration,@ratio,@goal,@notes)`)}if(input.references){await replace('ContentBriefReferences');for(const x of input.references)await new sql.Request(tx).input('bid',sql.UniqueIdentifier,brief.ContentBriefId).input('type',sql.NVarChar(50),x.referenceType).input('title',sql.NVarChar(250),x.title).input('url',sql.NVarChar(1000),x.url||null).input('notes',sql.NVarChar(1000),x.notes||null).input('required',sql.Bit,!!x.isRequired).query(`INSERT dbo.ContentBriefReferences(ContentBriefId,ReferenceType,Title,Url,Notes,IsRequired) VALUES(@bid,@type,@title,@url,@notes,@required)`)}if(input.successMetrics){await replace('ContentBriefSuccessMetrics');for(const m of input.successMetrics)await new sql.Request(tx).input('bid',sql.UniqueIdentifier,brief.ContentBriefId).input('key',sql.NVarChar(80),m.metricKey).input('name',sql.NVarChar(150),m.displayName).input('value',sql.Decimal(18,4),m.targetValue??null).input('unit',sql.NVarChar(50),m.targetUnit||null).input('ord',sql.Int,m.priorityOrder||1).input('notes',sql.NVarChar(500),m.notes||null).query(`INSERT dbo.ContentBriefSuccessMetrics(ContentBriefId,MetricKey,DisplayName,TargetValue,TargetUnit,PriorityOrder,Notes) VALUES(@bid,@key,@name,@value,@unit,@ord,@notes)`)}
 await new sql.Request(tx).input('pid',sql.UniqueIdentifier,projectId).input('uid',sql.UniqueIdentifier,userId).query(`INSERT dbo.ProjectActivities(ContentProjectId,ActivityType,StageKey,Title,Details,ActorType,ActorUserId) VALUES(@pid,'BRIEF_SAVED','STRATEGY_BRIEF','Content brief saved','Strategy & Content Brief saved as a working draft.','HUMAN',@uid)`);await tx.commit();return await getStrategyBrief(workspaceId,projectId)}catch(e){await tx.rollback();throw e}}
export async function submitStrategyBrief(workspaceId:string,projectId:string,userId:string,changeSummary?:string){const db=await getDb();const tx=new sql.Transaction(db);await tx.begin();try{const brief=(await new sql.Request(tx).input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).query(`SELECT b.* FROM dbo.ContentBriefs b JOIN dbo.ContentProjects p ON p.ContentProjectId=b.ContentProjectId WHERE b.ContentProjectId=@pid AND p.WorkspaceId=@ws`)).recordset[0];if(!brief)throw Object.assign(new Error('Save the brief before submitting it'),{statusCode:409});const next=Number((await new sql.Request(tx).input('bid2',sql.UniqueIdentifier,brief.ContentBriefId).query(`SELECT ISNULL(MAX(VersionNumber),0)+1 NextVersion FROM dbo.ContentBriefVersions WHERE ContentBriefId=@bid2`)).recordset[0]?.NextVersion||1);const snap=JSON.stringify(brief);await new sql.Request(tx).input('bid',sql.UniqueIdentifier,brief.ContentBriefId).input('n',sql.Int,next).input('snap',sql.NVarChar(sql.MAX),snap).input('summary',sql.NVarChar(1000),changeSummary||'Submitted for content strategy review.').input('uid',sql.UniqueIdentifier,userId).query(`INSERT dbo.ContentBriefVersions(ContentBriefId,VersionNumber,Status,SnapshotJson,ChangeSummary,CreatedByUserId) VALUES(@bid,@n,'IN_REVIEW',@snap,@summary,@uid); UPDATE dbo.ContentBriefs SET CurrentVersionNumber=@n,Status='IN_REVIEW',UpdatedAt=SYSUTCDATETIME() WHERE ContentBriefId=@bid`);await new sql.Request(tx).input('pid',sql.UniqueIdentifier,projectId).input('uid',sql.UniqueIdentifier,userId).query(`INSERT dbo.ProjectApprovals(ContentProjectId,StageKey,ApprovalType,Status,RequestedByUserId,AssignedToUserId,RequestNote) VALUES(@pid,'STRATEGY_BRIEF','Content Brief Approval','PENDING',@uid,@uid,'Review the complete strategic content brief before Opportunity Discovery.'); INSERT dbo.ProjectActivities(ContentProjectId,ActivityType,StageKey,Title,Details,ActorType,ActorUserId) VALUES(@pid,'BRIEF_SUBMITTED','STRATEGY_BRIEF','Content brief submitted','A versioned content brief was submitted for mandatory human approval.','HUMAN',@uid)`);await tx.commit();return await getStrategyBrief(workspaceId,projectId)}catch(e){await tx.rollback();throw e}}
export async function decideStrategyBrief(workspaceId:string,projectId:string,userId:string,decision:'APPROVE'|'RETURN',comment?:string){const db=await getDb();const tx=new sql.Transaction(db);await tx.begin();try{const brief=(await new sql.Request(tx).input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).query(`SELECT b.* FROM dbo.ContentBriefs b JOIN dbo.ContentProjects p ON p.ContentProjectId=b.ContentProjectId WHERE b.ContentProjectId=@pid AND p.WorkspaceId=@ws`)).recordset[0];if(!brief||brief.Status!=='IN_REVIEW')throw Object.assign(new Error('Brief is not awaiting review'),{statusCode:409});const version=(await new sql.Request(tx).input('bid',sql.UniqueIdentifier,brief.ContentBriefId).input('n',sql.Int,brief.CurrentVersionNumber).query(`SELECT TOP 1 ContentBriefVersionId FROM dbo.ContentBriefVersions WHERE ContentBriefId=@bid AND VersionNumber=@n`)).recordset[0];const approved=decision==='APPROVE';await new sql.Request(tx).input('bid',sql.UniqueIdentifier,brief.ContentBriefId).input('vid',sql.UniqueIdentifier,version?.ContentBriefVersionId||null).input('uid',sql.UniqueIdentifier,userId).input('status',sql.NVarChar(30),approved?'APPROVED':'RETURNED').input('comment',sql.NVarChar(2000),comment||null).query(`UPDATE dbo.ContentBriefVersions SET Status=@status,ReviewedByUserId=@uid,ReviewComment=@comment,ReviewedAt=SYSUTCDATETIME() WHERE ContentBriefVersionId=@vid; UPDATE dbo.ContentBriefs SET Status=@status,ApprovedVersionId=CASE WHEN @status='APPROVED' THEN @vid ELSE ApprovedVersionId END,ApprovedByUserId=CASE WHEN @status='APPROVED' THEN @uid ELSE NULL END,ApprovedAt=CASE WHEN @status='APPROVED' THEN SYSUTCDATETIME() ELSE NULL END,UpdatedAt=SYSUTCDATETIME() WHERE ContentBriefId=@bid`);await new sql.Request(tx).input('pid',sql.UniqueIdentifier,projectId).input('uid',sql.UniqueIdentifier,userId).input('decision',sql.NVarChar(30),approved?'APPROVED':'RETURNED').input('comment',sql.NVarChar(2000),comment||null).query(`UPDATE dbo.ProjectApprovals SET Status=CASE WHEN @decision='APPROVED' THEN 'APPROVED' ELSE 'RETURNED' END,DecisionByUserId=@uid,DecisionComment=@comment,DecidedAt=SYSUTCDATETIME() WHERE ProjectApprovalId=(SELECT TOP 1 ProjectApprovalId FROM dbo.ProjectApprovals WHERE ContentProjectId=@pid AND StageKey='STRATEGY_BRIEF' AND ApprovalType='Content Brief Approval' AND Status='PENDING' ORDER BY RequestedAt DESC); INSERT dbo.ProjectActivities(ContentProjectId,ActivityType,StageKey,Title,Details,ActorType,ActorUserId) VALUES(@pid,'BRIEF_DECISION','STRATEGY_BRIEF',CASE WHEN @decision='APPROVED' THEN 'Content brief approved' ELSE 'Content brief returned' END,COALESCE(@comment,'Strategy review decision recorded.'),'HUMAN',@uid)`);if(approved){await new sql.Request(tx).input('pid',sql.UniqueIdentifier,projectId).input('uid',sql.UniqueIdentifier,userId).input('vid',sql.UniqueIdentifier,version?.ContentBriefVersionId||null).query(`UPDATE dbo.ProjectStageExecutions SET Status='COMPLETED',ProgressPercent=100,CompletedAt=SYSUTCDATETIME(),UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId=(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey='STRATEGY_BRIEF'); UPDATE dbo.ProjectStageExecutions SET Status='NOT_STARTED',ProgressPercent=0,UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId=(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey='OPPORTUNITY_DISCOVERY') AND Status<>'COMPLETED'; INSERT dbo.ProjectHandoffs(ContentProjectId,FromStageKey,ToStageKey,OutputType,OutputReference,PayloadJson,Status,CreatedByUserId) VALUES(@pid,'STRATEGY_BRIEF','OPPORTUNITY_DISCOVERY','Approved Content Brief','CONTENT_BRIEF',JSON_OBJECT('contentBriefVersionId':CAST(@vid AS NVARCHAR(36))),'READY',@uid); INSERT dbo.ProjectVersions(ContentProjectId,VersionType,VersionNumber,SourceStageKey,Title,SnapshotJson,ChangeSummary,IsApproved,CreatedByUserId) SELECT @pid,'CONTENT_BRIEF',CurrentVersionNumber,'STRATEGY_BRIEF','Approved Content Brief',JSON_OBJECT('contentBriefId':CAST(ContentBriefId AS NVARCHAR(36)),'contentBriefVersionId':CAST(@vid AS NVARCHAR(36))),'Approved strategic direction handed to Opportunity Discovery.',1,@uid FROM dbo.ContentBriefs WHERE ContentProjectId=@pid`)}await tx.commit();return await getStrategyBrief(workspaceId,projectId)}catch(e){await tx.rollback();throw e}}

export async function listOpportunityProjects(workspaceId:string){const db=await getDb();const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).query(`SELECT p.ContentProjectId,p.ContentCode,p.WorkingTitle,p.Status ProjectStatus,b.Status BriefStatus,b.CurrentVersionNumber,COUNT(o.ContentOpportunityId) OpportunityCount,SUM(CASE WHEN o.Status='SHORTLISTED' THEN 1 ELSE 0 END) ShortlistedCount,SUM(CASE WHEN o.Status='SELECTED' THEN 1 ELSE 0 END) SelectedCount,MAX(o.OverallScore) TopScore,MAX(o.UpdatedAt) LastOpportunityAt FROM dbo.ContentProjects p LEFT JOIN dbo.ContentBriefs b ON b.ContentProjectId=p.ContentProjectId LEFT JOIN dbo.ContentOpportunities o ON o.ContentProjectId=p.ContentProjectId WHERE p.WorkspaceId=@ws GROUP BY p.ContentProjectId,p.ContentCode,p.WorkingTitle,p.Status,b.Status,b.CurrentVersionNumber ORDER BY p.UpdatedAt DESC`);return r.recordset}
export async function listOpportunities(workspaceId:string,projectId:string,filter?:{status?:string;search?:string}){const db=await getDb();let q=`SELECT o.* FROM dbo.ContentOpportunities o JOIN dbo.ContentProjects p ON p.ContentProjectId=o.ContentProjectId WHERE p.WorkspaceId=@ws AND o.ContentProjectId=@pid`;if(filter?.status&&filter.status!=='ALL')q+=` AND o.Status=@status`;if(filter?.search)q+=` AND (o.Title LIKE @search OR o.Topic LIKE @search OR o.Angle LIKE @search)`;q+=` ORDER BY o.OverallScore DESC,o.UpdatedAt DESC`;const req=db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId);if(filter?.status&&filter.status!=='ALL')req.input('status',sql.NVarChar(30),filter.status);if(filter?.search)req.input('search',sql.NVarChar(400),`%${filter.search}%`);return (await req.query(q)).recordset}
export async function getOpportunity(workspaceId:string,opportunityId:string){const db=await getDb();const opportunity=(await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('oid',sql.UniqueIdentifier,opportunityId).query(`SELECT o.*,p.ContentCode,p.WorkingTitle,b.CurrentVersionNumber BriefVersion,b.PrimaryObjective,b.AudienceSummary,b.CreativeDirection,b.ResearchFocus FROM dbo.ContentOpportunities o JOIN dbo.ContentProjects p ON p.ContentProjectId=o.ContentProjectId LEFT JOIN dbo.ContentBriefs b ON b.ContentProjectId=p.ContentProjectId WHERE p.WorkspaceId=@ws AND o.ContentOpportunityId=@oid`)).recordset[0];if(!opportunity)return null;const [signals,aud,decisions]=await Promise.all([db.request().input('oid',sql.UniqueIdentifier,opportunityId).query(`SELECT * FROM dbo.OpportunityTrendSignals WHERE ContentOpportunityId=@oid ORDER BY ObservedAt DESC,CreatedAt DESC`),db.request().input('oid',sql.UniqueIdentifier,opportunityId).query(`SELECT * FROM dbo.OpportunityAudienceScores WHERE ContentOpportunityId=@oid ORDER BY AppealScore DESC`),db.request().input('oid',sql.UniqueIdentifier,opportunityId).query(`SELECT d.*,u.DisplayName DecidedBy FROM dbo.OpportunityDecisions d LEFT JOIN dbo.Users u ON u.UserId=d.DecidedByUserId WHERE d.ContentOpportunityId=@oid ORDER BY d.DecidedAt DESC`)]);return {opportunity,signals:signals.recordset,audienceScores:aud.recordset,decisions:decisions.recordset}}
export async function createDiscoveryRun(workspaceId:string,projectId:string,userId:string,input:any){const db=await getDb();const approved=(await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).query(`SELECT TOP 1 b.ContentBriefId,b.ApprovedVersionId FROM dbo.ContentBriefs b JOIN dbo.ContentProjects p ON p.ContentProjectId=b.ContentProjectId WHERE p.WorkspaceId=@ws AND p.ContentProjectId=@pid AND b.Status='APPROVED'`)).recordset[0];if(!approved)throw Object.assign(new Error('An approved Strategy & Content Brief is required before Opportunity Discovery can run'),{statusCode:409});const r=await db.request().input('pid',sql.UniqueIdentifier,projectId).input('scope',sql.NVarChar(100),input.searchScope||'Global opportunity scan').input('queries',sql.NVarChar(sql.MAX),JSON.stringify(input.searchQueries||[])).input('markets',sql.NVarChar(sql.MAX),JSON.stringify(input.targetMarkets||[])).input('provider',sql.NVarChar(100),input.agentProvider||'Configured Opportunity Agent').input('model',sql.NVarChar(100),input.agentModel||null).input('uid',sql.UniqueIdentifier,userId).query(`INSERT dbo.OpportunityDiscoveryRuns(ContentProjectId,Status,SearchScope,SearchQueriesJson,TargetMarketsJson,AgentProvider,AgentModel,StartedAt,CreatedByUserId) OUTPUT inserted.* VALUES(@pid,'IN_PROGRESS',@scope,@queries,@markets,@provider,@model,SYSUTCDATETIME(),@uid)`);await db.request().input('pid',sql.UniqueIdentifier,projectId).query(`UPDATE dbo.ProjectStageExecutions SET Status='IN_PROGRESS',ProgressPercent=15,StartedAt=COALESCE(StartedAt,SYSUTCDATETIME()),UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId=(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey='OPPORTUNITY_DISCOVERY')`);return r.recordset[0]}
export async function decideOpportunity(workspaceId:string,opportunityId:string,userId:string,decision:'SHORTLIST'|'SELECT'|'REJECT'|'RESTORE',note?:string){const db=await getDb();const tx=new sql.Transaction(db);await tx.begin();try{const row=(await new sql.Request(tx).input('ws',sql.UniqueIdentifier,workspaceId).input('oid',sql.UniqueIdentifier,opportunityId).query(`SELECT o.ContentOpportunityId,o.ContentProjectId,o.Title,o.Status FROM dbo.ContentOpportunities o JOIN dbo.ContentProjects p ON p.ContentProjectId=o.ContentProjectId WHERE p.WorkspaceId=@ws AND o.ContentOpportunityId=@oid`)).recordset[0];if(!row)throw Object.assign(new Error('Opportunity not found'),{statusCode:404});const status=decision==='SHORTLIST'?'SHORTLISTED':decision==='SELECT'?'SELECTED':decision==='REJECT'?'REJECTED':'DISCOVERED';if(decision==='SELECT')await new sql.Request(tx).input('pid',sql.UniqueIdentifier,row.ContentProjectId).query(`UPDATE dbo.ContentOpportunities SET Status=CASE WHEN Status='SELECTED' THEN 'SHORTLISTED' ELSE Status END,SelectedAt=NULL,SelectedByUserId=NULL,UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND Status='SELECTED'`);await new sql.Request(tx).input('oid',sql.UniqueIdentifier,opportunityId).input('status',sql.NVarChar(30),status).input('note',sql.NVarChar(2000),note||null).input('uid',sql.UniqueIdentifier,userId).query(`UPDATE dbo.ContentOpportunities SET Status=@status,DecisionNote=@note,SelectedAt=CASE WHEN @status='SELECTED' THEN SYSUTCDATETIME() ELSE NULL END,SelectedByUserId=CASE WHEN @status='SELECTED' THEN @uid ELSE NULL END,UpdatedAt=SYSUTCDATETIME() WHERE ContentOpportunityId=@oid; INSERT dbo.OpportunityDecisions(ContentOpportunityId,Decision,Note,DecidedByUserId) VALUES(@oid,@status,@note,@uid)`);if(decision==='SELECT'){await new sql.Request(tx).input('pid',sql.UniqueIdentifier,row.ContentProjectId).input('oid',sql.UniqueIdentifier,opportunityId).input('uid',sql.UniqueIdentifier,userId).query(`UPDATE dbo.ProjectStageExecutions SET Status='COMPLETED',ProgressPercent=100,CompletedAt=SYSUTCDATETIME(),UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId=(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey='OPPORTUNITY_DISCOVERY'); UPDATE dbo.ProjectStageExecutions SET Status='NOT_STARTED',ProgressPercent=0,UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId=(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey='RESEARCH') AND Status<>'COMPLETED'; INSERT dbo.ProjectHandoffs(ContentProjectId,FromStageKey,ToStageKey,OutputType,OutputReference,PayloadJson,Status,CreatedByUserId) VALUES(@pid,'OPPORTUNITY_DISCOVERY','RESEARCH','Selected Content Opportunity',CAST(@oid AS NVARCHAR(36)),JSON_OBJECT('contentOpportunityId':CAST(@oid AS NVARCHAR(36))),'READY',@uid); INSERT dbo.ProjectVersions(ContentProjectId,VersionType,VersionNumber,SourceStageKey,Title,SnapshotJson,ChangeSummary,IsApproved,CreatedByUserId) SELECT @pid,'CONTENT_OPPORTUNITY',ISNULL((SELECT MAX(VersionNumber)+1 FROM dbo.ProjectVersions WHERE ContentProjectId=@pid AND VersionType='CONTENT_OPPORTUNITY'),1),'OPPORTUNITY_DISCOVERY',Title,JSON_OBJECT('contentOpportunityId':CAST(ContentOpportunityId AS NVARCHAR(36)),'title':Title,'score':OverallScore),'Selected opportunity handed to Research Studio.',1,@uid FROM dbo.ContentOpportunities WHERE ContentOpportunityId=@oid; INSERT dbo.ProjectActivities(ContentProjectId,ActivityType,StageKey,Title,Details,ActorType,ActorUserId) VALUES(@pid,'OPPORTUNITY_SELECTED','OPPORTUNITY_DISCOVERY','Opportunity selected','Selected opportunity completed discovery and was handed to Research Studio.','HUMAN',@uid)`)}await tx.commit();return {id:opportunityId,status}}catch(e){await tx.rollback();throw e}}

// Module 06 — Research & Fact Intelligence
export async function listResearchProjects(workspaceId:string){const db=await getDb();const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).query(`SELECT p.ContentProjectId,p.ContentCode,p.WorkingTitle,p.Status ProjectStatus,o.ContentOpportunityId,o.Title OpportunityTitle,o.OverallScore,rp.ResearchPackId,rp.Status ResearchStatus,rp.CurrentVersionNumber,rp.UpdatedAt,(SELECT COUNT(*) FROM dbo.ResearchSources s WHERE s.ResearchPackId=rp.ResearchPackId) SourceCount,(SELECT COUNT(*) FROM dbo.ResearchClaims c WHERE c.ResearchPackId=rp.ResearchPackId) ClaimCount,(SELECT COUNT(*) FROM dbo.ResearchClaims c WHERE c.ResearchPackId=rp.ResearchPackId AND c.VerificationStatus='VERIFIED') VerifiedClaimCount,(SELECT COUNT(*) FROM dbo.ResearchRisks rr WHERE rr.ResearchPackId=rp.ResearchPackId AND rr.Status<>'CLOSED') OpenRiskCount FROM dbo.ContentProjects p LEFT JOIN dbo.ContentOpportunities o ON o.ContentProjectId=p.ContentProjectId AND o.Status='SELECTED' LEFT JOIN dbo.ResearchPacks rp ON rp.ContentProjectId=p.ContentProjectId WHERE p.WorkspaceId=@ws ORDER BY p.UpdatedAt DESC`);return r.recordset}
export async function getResearchPack(workspaceId:string,projectId:string){const db=await getDb();const base=(await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).query(`SELECT p.ContentProjectId,p.ContentCode,p.WorkingTitle,o.ContentOpportunityId,o.Title OpportunityTitle,o.Angle,o.HookIdea,o.OverallScore,rp.* FROM dbo.ContentProjects p LEFT JOIN dbo.ContentOpportunities o ON o.ContentProjectId=p.ContentProjectId AND o.Status='SELECTED' LEFT JOIN dbo.ResearchPacks rp ON rp.ContentProjectId=p.ContentProjectId WHERE p.WorkspaceId=@ws AND p.ContentProjectId=@pid`)).recordset[0];if(!base)return null;if(!base.ResearchPackId)return {project:base,pack:null,questions:[],sources:[],claims:[],statistics:[],entities:[],timeline:[],contradictions:[],risks:[],versions:[]};const rid=base.ResearchPackId;const [questions,sources,claims,statistics,entities,timeline,contradictions,risks,versions]=await Promise.all([
 db.request().input('rid',sql.UniqueIdentifier,rid).query(`SELECT * FROM dbo.ResearchQuestions WHERE ResearchPackId=@rid ORDER BY SortOrder,CreatedAt`),
 db.request().input('rid',sql.UniqueIdentifier,rid).query(`SELECT * FROM dbo.ResearchSources WHERE ResearchPackId=@rid ORDER BY IsApproved DESC,AuthorityScore DESC,CreatedAt`),
 db.request().input('rid',sql.UniqueIdentifier,rid).query(`SELECT c.*, (SELECT COUNT(*) FROM dbo.ResearchClaimSources cs WHERE cs.ResearchClaimId=c.ResearchClaimId) EvidenceCount FROM dbo.ResearchClaims c WHERE c.ResearchPackId=@rid ORDER BY c.Materiality DESC,c.ClaimCode`),
 db.request().input('rid',sql.UniqueIdentifier,rid).query(`SELECT * FROM dbo.ResearchStatistics WHERE ResearchPackId=@rid ORDER BY CreatedAt`),
 db.request().input('rid',sql.UniqueIdentifier,rid).query(`SELECT * FROM dbo.ResearchEntities WHERE ResearchPackId=@rid ORDER BY EntityType,EntityName`),
 db.request().input('rid',sql.UniqueIdentifier,rid).query(`SELECT * FROM dbo.ResearchTimelineEvents WHERE ResearchPackId=@rid ORDER BY SortOrder,CreatedAt`),
 db.request().input('rid',sql.UniqueIdentifier,rid).query(`SELECT * FROM dbo.ResearchContradictions WHERE ResearchPackId=@rid ORDER BY CASE ResolutionStatus WHEN 'OPEN' THEN 0 ELSE 1 END,CreatedAt DESC`),
 db.request().input('rid',sql.UniqueIdentifier,rid).query(`SELECT * FROM dbo.ResearchRisks WHERE ResearchPackId=@rid ORDER BY CASE Severity WHEN 'CRITICAL' THEN 0 WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END,CreatedAt DESC`),
 db.request().input('rid',sql.UniqueIdentifier,rid).query(`SELECT * FROM dbo.ResearchPackVersions WHERE ResearchPackId=@rid ORDER BY VersionNumber DESC`)
 ]);return {project:base,pack:base,questions:questions.recordset,sources:sources.recordset,claims:claims.recordset,statistics:statistics.recordset,entities:entities.recordset,timeline:timeline.recordset,contradictions:contradictions.recordset,risks:risks.recordset,versions:versions.recordset}}
export async function startResearchPack(workspaceId:string,projectId:string,userId:string,input:any){const db=await getDb();const selected=(await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).query(`SELECT TOP 1 o.ContentOpportunityId FROM dbo.ContentOpportunities o JOIN dbo.ContentProjects p ON p.ContentProjectId=o.ContentProjectId WHERE p.WorkspaceId=@ws AND p.ContentProjectId=@pid AND o.Status='SELECTED'`)).recordset[0];if(!selected)throw Object.assign(new Error('A selected opportunity is required before Research can start'),{statusCode:409});await db.request().input('pid',sql.UniqueIdentifier,projectId).input('oid',sql.UniqueIdentifier,selected.ContentOpportunityId).input('uid',sql.UniqueIdentifier,userId).input('objective',sql.NVarChar(1500),input.researchObjective||null).input('provider',sql.NVarChar(120),input.provider||'Configured Research Agent').input('model',sql.NVarChar(120),input.model||null).query(`IF EXISTS(SELECT 1 FROM dbo.ResearchPacks WHERE ContentProjectId=@pid) UPDATE dbo.ResearchPacks SET Status='IN_PROGRESS',ResearchObjective=COALESCE(@objective,ResearchObjective),ResearchProvider=@provider,ResearchModel=@model,StartedAt=COALESCE(StartedAt,SYSUTCDATETIME()),UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid ELSE INSERT dbo.ResearchPacks(ContentProjectId,SourceOpportunityId,Status,ResearchObjective,ResearchProvider,ResearchModel,StartedAt,CreatedByUserId) VALUES(@pid,@oid,'IN_PROGRESS',@objective,@provider,@model,SYSUTCDATETIME(),@uid); UPDATE dbo.ProjectStageExecutions SET Status='IN_PROGRESS',ProgressPercent=10,StartedAt=COALESCE(StartedAt,SYSUTCDATETIME()),UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId=(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey='RESEARCH')`);return await getResearchPack(workspaceId,projectId)}
export async function saveResearchPack(workspaceId:string,projectId:string,userId:string,input:any){const db=await getDb();const pack=(await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).query(`SELECT rp.ResearchPackId FROM dbo.ResearchPacks rp JOIN dbo.ContentProjects p ON p.ContentProjectId=rp.ContentProjectId WHERE p.WorkspaceId=@ws AND p.ContentProjectId=@pid`)).recordset[0];if(!pack)throw Object.assign(new Error('Start Research first'),{statusCode:409});await db.request().input('rid',sql.UniqueIdentifier,pack.ResearchPackId).input('objective',sql.NVarChar(1500),input.researchObjective||null).input('summary',sql.NVarChar(sql.MAX),input.researchSummary||null).input('findings',sql.NVarChar(sql.MAX),input.executiveFindings||null).input('angles',sql.NVarChar(sql.MAX),input.narrativeAngles||null).input('production',sql.NVarChar(sql.MAX),input.productionNotes||null).input('sensitivity',sql.NVarChar(sql.MAX),input.sensitivitySummary||null).query(`UPDATE dbo.ResearchPacks SET ResearchObjective=COALESCE(@objective,ResearchObjective),ResearchSummary=@summary,ExecutiveFindings=@findings,NarrativeAngles=@angles,ProductionNotes=@production,SensitivitySummary=@sensitivity,UpdatedAt=SYSUTCDATETIME() WHERE ResearchPackId=@rid`);await db.request().input('pid',sql.UniqueIdentifier,projectId).query(`UPDATE dbo.ProjectStageExecutions SET ProgressPercent=CASE WHEN ProgressPercent<65 THEN 65 ELSE ProgressPercent END,UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId=(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey='RESEARCH')`);return await getResearchPack(workspaceId,projectId)}
export async function addResearchSource(workspaceId:string,projectId:string,userId:string,input:any){const db=await getDb();const pack=(await getResearchPack(workspaceId,projectId)) as any;if(!pack?.pack?.ResearchPackId)throw Object.assign(new Error('Research Pack not found'),{statusCode:404});const r=await db.request().input('rid',sql.UniqueIdentifier,pack.pack.ResearchPackId).input('type',sql.NVarChar(60),input.sourceType).input('publisher',sql.NVarChar(200),input.publisher||null).input('title',sql.NVarChar(500),input.title).input('url',sql.NVarChar(1500),input.url||null).input('author',sql.NVarChar(250),input.author||null).input('quality',sql.NVarChar(30),input.sourceQuality||'UNASSESSED').input('authority',sql.Decimal(5,2),input.authorityScore||0).input('recency',sql.Decimal(5,2),input.recencyScore||0).input('relevance',sql.Decimal(5,2),input.relevanceScore||0).input('primary',sql.Bit,input.isPrimarySource?1:0).input('notes',sql.NVarChar(sql.MAX),input.notes||null).query(`INSERT dbo.ResearchSources(ResearchPackId,SourceType,Publisher,Title,Url,Author,SourceQuality,AuthorityScore,RecencyScore,RelevanceScore,IsPrimarySource,Notes,AccessedAt) OUTPUT inserted.* VALUES(@rid,@type,@publisher,@title,@url,@author,@quality,@authority,@recency,@relevance,@primary,@notes,SYSUTCDATETIME())`);return r.recordset[0]}
export async function updateResearchClaim(workspaceId:string,claimId:string,userId:string,input:any){const db=await getDb();const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('cid',sql.UniqueIdentifier,claimId).input('status',sql.NVarChar(30),input.verificationStatus).input('conf',sql.Decimal(5,2),input.confidenceScore).input('usage',sql.NVarChar(30),input.scriptUsageStatus).input('notes',sql.NVarChar(sql.MAX),input.verificationNotes||null).input('uid',sql.UniqueIdentifier,userId).query(`UPDATE c SET VerificationStatus=@status,ConfidenceScore=@conf,ScriptUsageStatus=@usage,VerificationNotes=@notes,VerifiedByUserId=@uid,VerifiedAt=SYSUTCDATETIME(),UpdatedAt=SYSUTCDATETIME() OUTPUT inserted.* FROM dbo.ResearchClaims c JOIN dbo.ResearchPacks rp ON rp.ResearchPackId=c.ResearchPackId JOIN dbo.ContentProjects p ON p.ContentProjectId=rp.ContentProjectId WHERE c.ResearchClaimId=@cid AND p.WorkspaceId=@ws`);return r.recordset[0]||null}
export async function submitResearchPack(workspaceId:string,projectId:string,userId:string,changeSummary?:string){const db=await getDb();const pack=(await getResearchPack(workspaceId,projectId)) as any;if(!pack?.pack?.ResearchPackId)throw Object.assign(new Error('Research Pack not found'),{statusCode:404});const openCritical=(pack.claims||[]).filter((c:any)=>c.Materiality==='HIGH'&&['UNVERIFIED','CONFLICTING','NEEDS_REVIEW'].includes(c.VerificationStatus)).length;if(openCritical)throw Object.assign(new Error(`${openCritical} high-materiality claim(s) require verification before review`),{statusCode:409});const version=(pack.pack.CurrentVersionNumber||0)+1;const snapshot=JSON.stringify({researchSummary:pack.pack.ResearchSummary,executiveFindings:pack.pack.ExecutiveFindings,narrativeAngles:pack.pack.NarrativeAngles,sourceCount:pack.sources.length,claimCount:pack.claims.length,verifiedClaims:pack.claims.filter((x:any)=>x.VerificationStatus==='VERIFIED').length,openRisks:pack.risks.filter((x:any)=>x.Status!=='CLOSED').length});const r=await db.request().input('rid',sql.UniqueIdentifier,pack.pack.ResearchPackId).input('v',sql.Int,version).input('snapshot',sql.NVarChar(sql.MAX),snapshot).input('summary',sql.NVarChar(1500),changeSummary||'Research Pack submitted for human review.').input('uid',sql.UniqueIdentifier,userId).query(`INSERT dbo.ResearchPackVersions(ResearchPackId,VersionNumber,Status,SnapshotJson,ChangeSummary,CreatedByUserId) OUTPUT inserted.* VALUES(@rid,@v,'IN_REVIEW',@snapshot,@summary,@uid); UPDATE dbo.ResearchPacks SET Status='IN_REVIEW',CurrentVersionNumber=@v,SubmittedAt=SYSUTCDATETIME(),UpdatedAt=SYSUTCDATETIME() WHERE ResearchPackId=@rid`);await db.request().input('pid',sql.UniqueIdentifier,projectId).query(`UPDATE dbo.ProjectStageExecutions SET Status='AWAITING_APPROVAL',ProgressPercent=90,UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId=(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey='RESEARCH')`);return r.recordset[0]}
export async function decideResearchPack(workspaceId:string,projectId:string,userId:string,decision:'APPROVE'|'RETURN',comment?:string){const db=await getDb();const pack=(await getResearchPack(workspaceId,projectId)) as any;if(!pack?.pack?.ResearchPackId)throw Object.assign(new Error('Research Pack not found'),{statusCode:404});if(pack.pack.Status!=='IN_REVIEW')throw Object.assign(new Error('Research Pack is not awaiting review'),{statusCode:409});const tx=new sql.Transaction(db);await tx.begin();try{if(decision==='RETURN'){await new sql.Request(tx).input('rid',sql.UniqueIdentifier,pack.pack.ResearchPackId).input('pid',sql.UniqueIdentifier,projectId).query(`UPDATE dbo.ResearchPacks SET Status='RETURNED',UpdatedAt=SYSUTCDATETIME() WHERE ResearchPackId=@rid; UPDATE dbo.ProjectStageExecutions SET Status='IN_PROGRESS',ProgressPercent=75,UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId=(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey='RESEARCH')`);}else{const v=(await new sql.Request(tx).input('rid',sql.UniqueIdentifier,pack.pack.ResearchPackId).query(`SELECT TOP 1 ResearchPackVersionId,VersionNumber FROM dbo.ResearchPackVersions WHERE ResearchPackId=@rid ORDER BY VersionNumber DESC`)).recordset[0];if(!v)throw Object.assign(new Error('Submit the Research Pack before approval'),{statusCode:409});await new sql.Request(tx).input('rid',sql.UniqueIdentifier,pack.pack.ResearchPackId).input('vid',sql.UniqueIdentifier,v.ResearchPackVersionId).input('version',sql.Int,v.VersionNumber).input('uid',sql.UniqueIdentifier,userId).input('pid',sql.UniqueIdentifier,projectId).query(`UPDATE dbo.ResearchPacks SET Status='APPROVED',ApprovedVersionId=@vid,ApprovedAt=SYSUTCDATETIME(),ApprovedByUserId=@uid,UpdatedAt=SYSUTCDATETIME() WHERE ResearchPackId=@rid; UPDATE dbo.ResearchPackVersions SET Status='APPROVED' WHERE ResearchPackVersionId=@vid; UPDATE dbo.ProjectStageExecutions SET Status='COMPLETED',ProgressPercent=100,CompletedAt=SYSUTCDATETIME(),UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId=(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey='RESEARCH'); UPDATE dbo.ProjectStageExecutions SET Status='NOT_STARTED',ProgressPercent=0,UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId=(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey='CONCEPT_APPROVAL') AND Status<>'COMPLETED'; INSERT dbo.ProjectVersions(ContentProjectId,VersionType,VersionNumber,SourceStageKey,Title,SnapshotJson,ChangeSummary,IsApproved,CreatedByUserId) VALUES(@pid,'RESEARCH_PACK',@version,'RESEARCH','Approved Research Pack',JSON_OBJECT('researchPackId':CAST(@rid AS NVARCHAR(36)),'version':@version),'Research Pack approved for Concept & Script Production.',1,@uid); INSERT dbo.ProjectHandoffs(ContentProjectId,FromStageKey,ToStageKey,OutputType,OutputReference,PayloadJson,Status,CreatedByUserId) VALUES(@pid,'RESEARCH','CONCEPT_APPROVAL','Approved Research Pack',CAST(@vid AS NVARCHAR(36)),JSON_OBJECT('researchPackId':CAST(@rid AS NVARCHAR(36)),'researchPackVersionId':CAST(@vid AS NVARCHAR(36)),'version':@version),'READY',@uid); INSERT dbo.ProjectActivities(ContentProjectId,ActivityType,StageKey,Title,Details,ActorType,ActorUserId) VALUES(@pid,'RESEARCH_APPROVED','RESEARCH','Research Pack approved','Verified research output handed to Concept & Script Production.','HUMAN',@uid)`);}await tx.commit();return {ok:true,status:decision==='APPROVE'?'APPROVED':'RETURNED'}}catch(e){await tx.rollback();throw e}}

/* Module 07 — Concept & Script Production */
export async function listScriptProjects(workspaceId:string){const db=await getDb();const r=await db.request().input('ws',sql.UniqueIdentifier,workspaceId).query(`SELECT p.ContentProjectId,p.ContentCode,p.WorkingTitle,p.Status ProjectStatus,sd.ScriptDocumentId,sd.Status ScriptStatus,sd.CurrentVersionNumber,sd.TotalWords,sd.ActualDurationSeconds,sd.RetentionScore,sd.ResearchComplianceScore,sc.ConceptCode,sc.Title ConceptTitle,sc.OverallScore ConceptScore FROM dbo.ContentProjects p LEFT JOIN dbo.ScriptDocuments sd ON sd.ContentProjectId=p.ContentProjectId LEFT JOIN dbo.ScriptConcepts sc ON sc.ScriptConceptId=sd.ScriptConceptId WHERE p.WorkspaceId=@ws AND EXISTS(SELECT 1 FROM dbo.ResearchPacks rp WHERE rp.ContentProjectId=p.ContentProjectId AND rp.Status='APPROVED') ORDER BY p.UpdatedAt DESC`);return r.recordset}
export async function getScriptWorkspace(workspaceId:string,projectId:string){const db=await getDb();const project=(await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).query(`SELECT p.ContentProjectId,p.ContentCode,p.WorkingTitle,p.PlannedDurationSeconds,p.Language,rp.ResearchPackId,rp.ApprovedVersionId ResearchPackVersionId,rp.CurrentVersionNumber ResearchVersion FROM dbo.ContentProjects p JOIN dbo.ResearchPacks rp ON rp.ContentProjectId=p.ContentProjectId AND rp.Status='APPROVED' WHERE p.WorkspaceId=@ws AND p.ContentProjectId=@pid`)).recordset[0];if(!project)return null;const [concepts,docs]=await Promise.all([db.request().input('pid',sql.UniqueIdentifier,projectId).query(`SELECT * FROM dbo.ScriptConcepts WHERE ContentProjectId=@pid ORDER BY CASE Status WHEN 'APPROVED' THEN 0 WHEN 'SELECTED' THEN 1 WHEN 'SHORTLISTED' THEN 2 ELSE 3 END,OverallScore DESC,CreatedAt`),db.request().input('pid',sql.UniqueIdentifier,projectId).query(`SELECT * FROM dbo.ScriptDocuments WHERE ContentProjectId=@pid`)]);const doc=docs.recordset[0]||null;if(!doc)return {project,concepts:concepts.recordset,document:null,sections:[],claimLinks:[],retention:[],versions:[]};const [sections,links,retention,versions,reviews]=await Promise.all([db.request().input('sid',sql.UniqueIdentifier,doc.ScriptDocumentId).query(`SELECT * FROM dbo.ScriptSections WHERE ScriptDocumentId=@sid ORDER BY SectionOrder`),db.request().input('sid',sql.UniqueIdentifier,doc.ScriptDocumentId).query(`SELECT scl.*,rc.ClaimCode,rc.ClaimText,rc.VerificationStatus,rc.ConfidenceScore,rc.ScriptUsageStatus FROM dbo.ScriptClaimLinks scl JOIN dbo.ResearchClaims rc ON rc.ResearchClaimId=scl.ResearchClaimId WHERE scl.ScriptDocumentId=@sid ORDER BY scl.CreatedAt`),db.request().input('sid',sql.UniqueIdentifier,doc.ScriptDocumentId).query(`SELECT * FROM dbo.ScriptRetentionChecks WHERE ScriptDocumentId=@sid ORDER BY StartSecond,CreatedAt`),db.request().input('sid',sql.UniqueIdentifier,doc.ScriptDocumentId).query(`SELECT * FROM dbo.ScriptVersions WHERE ScriptDocumentId=@sid ORDER BY VersionNumber DESC`),db.request().input('sid',sql.UniqueIdentifier,doc.ScriptDocumentId).query(`SELECT * FROM dbo.ScriptReviews WHERE ScriptDocumentId=@sid ORDER BY CreatedAt DESC`)]);return {project,concepts:concepts.recordset,document:doc,sections:sections.recordset,claimLinks:links.recordset,retention:retention.recordset,versions:versions.recordset,reviews:reviews.recordset}}
export async function generateScriptConcepts(workspaceId:string,projectId:string,userId:string,input:any){const db=await getDb();const pack=(await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).query(`SELECT TOP 1 rp.ResearchPackId,rp.ApprovedVersionId FROM dbo.ResearchPacks rp JOIN dbo.ContentProjects p ON p.ContentProjectId=rp.ContentProjectId WHERE p.WorkspaceId=@ws AND p.ContentProjectId=@pid AND rp.Status='APPROVED'`)).recordset[0];if(!pack)throw Object.assign(new Error('Approved Research Pack is required before concept generation'),{statusCode:409});const candidates=input.concepts?.length?input.concepts:[{title:'Your Day Was Predicted Before Breakfast',angle:'Reveal invisible AI through one ordinary day.',hook:'Before breakfast, several AI systems had already influenced what appeared in front of you.',structure:['Cold open','Morning','Commute','Work','Limits','Takeaway'],score:92}];const tx=new sql.Transaction(db);await tx.begin();try{for(let i=0;i<candidates.length;i++){const c=candidates[i];await new sql.Request(tx).input('pid',sql.UniqueIdentifier,projectId).input('rpv',sql.UniqueIdentifier,pack.ApprovedVersionId).input('code',sql.NVarChar(30),`CON-${String(i+1).padStart(3,'0')}`).input('title',sql.NVarChar(300),c.title).input('angle',sql.NVarChar(sql.MAX),c.angle||null).input('hook',sql.NVarChar(sql.MAX),c.hook||null).input('structure',sql.NVarChar(sql.MAX),JSON.stringify(c.structure||[])).input('score',sql.Decimal(5,2),c.score||0).query(`IF NOT EXISTS(SELECT 1 FROM dbo.ScriptConcepts WHERE ContentProjectId=@pid AND ConceptCode=@code) INSERT dbo.ScriptConcepts(ContentProjectId,ResearchPackVersionId,ConceptCode,Title,Angle,Hook,StructureJson,OverallScore,RetentionScore,GlobalAppealScore,VisualPotentialScore,FactualSafetyScore) VALUES(@pid,@rpv,@code,@title,@angle,@hook,@structure,@score,@score,@score,@score,@score)`)}await new sql.Request(tx).input('pid',sql.UniqueIdentifier,projectId).query(`UPDATE dbo.ProjectStageExecutions SET Status='IN_PROGRESS',ProgressPercent=40,StartedAt=COALESCE(StartedAt,SYSUTCDATETIME()),UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId=(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey='CONCEPT_APPROVAL')`);await tx.commit();return await getScriptWorkspace(workspaceId,projectId)}catch(e){await tx.rollback();throw e}}
export async function decideScriptConcept(workspaceId:string,projectId:string,conceptId:string,userId:string,decision:'SHORTLIST'|'SELECT'|'REJECT'|'APPROVE'){const db=await getDb();const c=(await db.request().input('ws',sql.UniqueIdentifier,workspaceId).input('pid',sql.UniqueIdentifier,projectId).input('cid',sql.UniqueIdentifier,conceptId).query(`SELECT sc.* FROM dbo.ScriptConcepts sc JOIN dbo.ContentProjects p ON p.ContentProjectId=sc.ContentProjectId WHERE p.WorkspaceId=@ws AND sc.ContentProjectId=@pid AND sc.ScriptConceptId=@cid`)).recordset[0];if(!c)throw Object.assign(new Error('Concept not found'),{statusCode:404});const next=decision==='SHORTLIST'?'SHORTLISTED':decision==='REJECT'?'REJECTED':decision==='APPROVE'?'APPROVED':'SELECTED';const tx=new sql.Transaction(db);await tx.begin();try{if(decision==='SELECT'||decision==='APPROVE')await new sql.Request(tx).input('pid',sql.UniqueIdentifier,projectId).query(`UPDATE dbo.ScriptConcepts SET Status=CASE WHEN Status IN('SELECTED','APPROVED') THEN 'SHORTLISTED' ELSE Status END,UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid`);await new sql.Request(tx).input('cid',sql.UniqueIdentifier,conceptId).input('next',sql.NVarChar(30),next).input('uid',sql.UniqueIdentifier,userId).query(`UPDATE dbo.ScriptConcepts SET Status=@next,SelectedAt=CASE WHEN @next IN('SELECTED','APPROVED') THEN SYSUTCDATETIME() ELSE SelectedAt END,SelectedByUserId=CASE WHEN @next IN('SELECTED','APPROVED') THEN @uid ELSE SelectedByUserId END,UpdatedAt=SYSUTCDATETIME() WHERE ScriptConceptId=@cid`);if(decision==='APPROVE'){await new sql.Request(tx).input('pid',sql.UniqueIdentifier,projectId).query(`UPDATE dbo.ProjectStageExecutions SET Status='COMPLETED',ProgressPercent=100,CompletedAt=SYSUTCDATETIME(),UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId=(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey='CONCEPT_APPROVAL'); UPDATE dbo.ProjectStageExecutions SET Status='NOT_STARTED',ProgressPercent=0,UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId=(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey='SCRIPT') AND Status<>'COMPLETED'`)}await tx.commit();return {ok:true,status:next}}catch(e){await tx.rollback();throw e}}
export async function startScriptDocument(workspaceId:string,projectId:string,userId:string,input:any){const db=await getDb();const ctx=await getScriptWorkspace(workspaceId,projectId) as any;if(!ctx)throw Object.assign(new Error('Project or approved Research Pack not found'),{statusCode:404});const concept=(ctx.concepts||[]).find((x:any)=>x.Status==='APPROVED')||(ctx.concepts||[]).find((x:any)=>x.Status==='SELECTED');if(!concept)throw Object.assign(new Error('Approve a concept before starting the script'),{statusCode:409});if(ctx.document)return ctx;const r=await db.request().input('pid',sql.UniqueIdentifier,projectId).input('cid',sql.UniqueIdentifier,concept.ScriptConceptId).input('rpv',sql.UniqueIdentifier,ctx.project.ResearchPackVersionId).input('dur',sql.Int,input.targetDurationSeconds||ctx.project.PlannedDurationSeconds||540).input('lang',sql.NVarChar(50),input.language||ctx.project.Language||'English').input('voice',sql.NVarChar(30),input.voiceMode||'NARRATION').input('tone',sql.NVarChar(120),input.tone||'Clear cinematic documentary').input('uid',sql.UniqueIdentifier,userId).query(`INSERT dbo.ScriptDocuments(ContentProjectId,ScriptConceptId,ApprovedResearchPackVersionId,TargetDurationSeconds,Language,VoiceMode,Tone,CreatedByUserId) OUTPUT inserted.* VALUES(@pid,@cid,@rpv,@dur,@lang,@voice,@tone,@uid)`);await db.request().input('pid',sql.UniqueIdentifier,projectId).query(`UPDATE dbo.ProjectStageExecutions SET Status='IN_PROGRESS',ProgressPercent=10,StartedAt=COALESCE(StartedAt,SYSUTCDATETIME()),UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId=(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey='SCRIPT')`);return await getScriptWorkspace(workspaceId,projectId)}
export async function saveScriptSections(workspaceId:string,projectId:string,userId:string,input:any){const db=await getDb();const ctx=await getScriptWorkspace(workspaceId,projectId) as any;if(!ctx?.document)throw Object.assign(new Error('Start Script Studio first'),{statusCode:409});const tx=new sql.Transaction(db);await tx.begin();try{for(const s of input.sections||[]){const words=String(s.body||'').trim().split(/\s+/).filter(Boolean).length;await new sql.Request(tx).input('sid',sql.UniqueIdentifier,ctx.document.ScriptDocumentId).input('ord',sql.Int,s.order).input('type',sql.NVarChar(30),s.type||'CHAPTER').input('title',sql.NVarChar(250),s.title).input('start',sql.Int,s.startSecond??null).input('end',sql.Int,s.endSecond??null).input('body',sql.NVarChar(sql.MAX),s.body).input('words',sql.Int,words).input('purpose',sql.NVarChar(1000),s.purpose||null).query(`MERGE dbo.ScriptSections t USING(SELECT @sid ScriptDocumentId,@ord SectionOrder) x ON t.ScriptDocumentId=x.ScriptDocumentId AND t.SectionOrder=x.SectionOrder WHEN MATCHED THEN UPDATE SET SectionType=@type,Title=@title,StartSecond=@start,EndSecond=@end,Body=@body,WordCount=@words,SectionPurpose=@purpose,UpdatedAt=SYSUTCDATETIME() WHEN NOT MATCHED THEN INSERT(ScriptDocumentId,SectionOrder,SectionType,Title,StartSecond,EndSecond,Body,WordCount,SectionPurpose) VALUES(@sid,@ord,@type,@title,@start,@end,@body,@words,@purpose);`)}await new sql.Request(tx).input('sid',sql.UniqueIdentifier,ctx.document.ScriptDocumentId).input('pid',sql.UniqueIdentifier,projectId).query(`UPDATE dbo.ScriptDocuments SET TotalWords=(SELECT ISNULL(SUM(WordCount),0) FROM dbo.ScriptSections WHERE ScriptDocumentId=@sid),ActualDurationSeconds=(SELECT MAX(EndSecond) FROM dbo.ScriptSections WHERE ScriptDocumentId=@sid),UpdatedAt=SYSUTCDATETIME() WHERE ScriptDocumentId=@sid; UPDATE dbo.ProjectStageExecutions SET ProgressPercent=CASE WHEN ProgressPercent<70 THEN 70 ELSE ProgressPercent END,UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId=(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey='SCRIPT')`);await tx.commit();return await getScriptWorkspace(workspaceId,projectId)}catch(e){await tx.rollback();throw e}}
export async function submitScript(workspaceId:string,projectId:string,userId:string,changeSummary?:string){const db=await getDb();const ctx=await getScriptWorkspace(workspaceId,projectId) as any;if(!ctx?.document)throw Object.assign(new Error('Script not found'),{statusCode:404});const blocked=(ctx.claimLinks||[]).filter((x:any)=>x.IsMaterial&&(x.VerificationStatus!=='VERIFIED'||x.ScriptUsageStatus!=='APPROVED')).length;const blockingRetention=(ctx.retention||[]).filter((x:any)=>x.IsBlocking&&!x.ResolvedAt).length;if(blocked||blockingRetention)throw Object.assign(new Error(`Script has ${blocked} blocked factual link(s) and ${blockingRetention} blocking retention issue(s)`),{statusCode:409});const next=(ctx.document.CurrentVersionNumber||0)+1;const snapshot=JSON.stringify({conceptId:ctx.document.ScriptConceptId,sections:ctx.sections,claimLinks:ctx.claimLinks,retention:ctx.retention,totalWords:ctx.document.TotalWords,durationSeconds:ctx.document.ActualDurationSeconds});const r=await db.request().input('sid',sql.UniqueIdentifier,ctx.document.ScriptDocumentId).input('v',sql.Int,next).input('snap',sql.NVarChar(sql.MAX),snapshot).input('summary',sql.NVarChar(1500),changeSummary||'Script submitted for human review.').input('words',sql.Int,ctx.document.TotalWords||0).input('dur',sql.Int,ctx.document.ActualDurationSeconds||null).input('uid',sql.UniqueIdentifier,userId).query(`INSERT dbo.ScriptVersions(ScriptDocumentId,VersionNumber,Status,SnapshotJson,ChangeSummary,WordCount,DurationSeconds,CreatedByUserId) OUTPUT inserted.* VALUES(@sid,@v,'IN_REVIEW',@snap,@summary,@words,@dur,@uid); UPDATE dbo.ScriptDocuments SET Status='IN_REVIEW',CurrentVersionNumber=@v,SubmittedAt=SYSUTCDATETIME(),UpdatedAt=SYSUTCDATETIME() WHERE ScriptDocumentId=@sid`);await db.request().input('pid',sql.UniqueIdentifier,projectId).query(`UPDATE dbo.ProjectStageExecutions SET Status='AWAITING_APPROVAL',ProgressPercent=92,UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId=(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey='SCRIPT')`);return r.recordset[0]}
export async function decideScript(workspaceId:string,projectId:string,userId:string,decision:'APPROVE'|'RETURN',comment?:string){const db=await getDb();const ctx=await getScriptWorkspace(workspaceId,projectId) as any;if(!ctx?.document)throw Object.assign(new Error('Script not found'),{statusCode:404});if(ctx.document.Status!=='IN_REVIEW')throw Object.assign(new Error('Script is not awaiting review'),{statusCode:409});const v=ctx.versions[0];if(!v)throw Object.assign(new Error('No submitted script version found'),{statusCode:409});const tx=new sql.Transaction(db);await tx.begin();try{await new sql.Request(tx).input('sid',sql.UniqueIdentifier,ctx.document.ScriptDocumentId).input('vid',sql.UniqueIdentifier,v.ScriptVersionId).input('uid',sql.UniqueIdentifier,userId).input('decision',sql.NVarChar(30),decision).input('comment',sql.NVarChar(sql.MAX),comment||null).query(`INSERT dbo.ScriptReviews(ScriptDocumentId,ScriptVersionId,Decision,Comment,ReviewerUserId) VALUES(@sid,@vid,@decision,@comment,@uid)`);if(decision==='RETURN'){await new sql.Request(tx).input('sid',sql.UniqueIdentifier,ctx.document.ScriptDocumentId).input('vid',sql.UniqueIdentifier,v.ScriptVersionId).input('pid',sql.UniqueIdentifier,projectId).query(`UPDATE dbo.ScriptDocuments SET Status='RETURNED',UpdatedAt=SYSUTCDATETIME() WHERE ScriptDocumentId=@sid; UPDATE dbo.ScriptVersions SET Status='RETURNED' WHERE ScriptVersionId=@vid; UPDATE dbo.ProjectStageExecutions SET Status='IN_PROGRESS',ProgressPercent=75,UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId=(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey='SCRIPT')`)}else{await new sql.Request(tx).input('sid',sql.UniqueIdentifier,ctx.document.ScriptDocumentId).input('vid',sql.UniqueIdentifier,v.ScriptVersionId).input('v',sql.Int,v.VersionNumber).input('uid',sql.UniqueIdentifier,userId).input('pid',sql.UniqueIdentifier,projectId).query(`UPDATE dbo.ScriptDocuments SET Status='APPROVED',ApprovedVersionId=@vid,ApprovedAt=SYSUTCDATETIME(),ApprovedByUserId=@uid,UpdatedAt=SYSUTCDATETIME() WHERE ScriptDocumentId=@sid; UPDATE dbo.ScriptVersions SET Status='APPROVED',ReviewedByUserId=@uid,ReviewedAt=SYSUTCDATETIME() WHERE ScriptVersionId=@vid; UPDATE dbo.ProjectStageExecutions SET Status='COMPLETED',ProgressPercent=100,CompletedAt=SYSUTCDATETIME(),UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId=(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey='SCRIPT'); UPDATE dbo.ProjectStageExecutions SET Status='NOT_STARTED',ProgressPercent=0,UpdatedAt=SYSUTCDATETIME() WHERE ContentProjectId=@pid AND WorkflowStageDefinitionId IN(SELECT WorkflowStageDefinitionId FROM dbo.WorkflowStageDefinitions WHERE StageKey IN('FACT_CHECK','CHARACTER_BIBLE','SCENE_MATRIX')) AND Status<>'COMPLETED'; INSERT dbo.ProjectVersions(ContentProjectId,VersionType,VersionNumber,SourceStageKey,Title,SnapshotJson,ChangeSummary,IsApproved,CreatedByUserId) VALUES(@pid,'SCRIPT',@v,'SCRIPT','Approved Script',JSON_OBJECT('scriptDocumentId':CAST(@sid AS NVARCHAR(36)),'scriptVersionId':CAST(@vid AS NVARCHAR(36)),'version':@v),'Script approved for production planning.',1,@uid); INSERT dbo.ProjectHandoffs(ContentProjectId,FromStageKey,ToStageKey,OutputType,OutputReference,PayloadJson,Status,CreatedByUserId) VALUES(@pid,'SCRIPT','CHARACTER_BIBLE','Approved Script Package',CAST(@vid AS NVARCHAR(36)),JSON_OBJECT('scriptDocumentId':CAST(@sid AS NVARCHAR(36)),'scriptVersionId':CAST(@vid AS NVARCHAR(36)),'version':@v),'READY',@uid),(@pid,'SCRIPT','SCENE_MATRIX','Approved Script Package',CAST(@vid AS NVARCHAR(36)),JSON_OBJECT('scriptDocumentId':CAST(@sid AS NVARCHAR(36)),'scriptVersionId':CAST(@vid AS NVARCHAR(36)),'version':@v),'READY',@uid); INSERT dbo.ProjectActivities(ContentProjectId,ActivityType,StageKey,Title,Details,ActorType,ActorUserId) VALUES(@pid,'SCRIPT_APPROVED','SCRIPT','Script approved','Approved script handed to Character Bible and Scene Matrix.','HUMAN',@uid)`)}await tx.commit();return {ok:true,status:decision==='APPROVE'?'APPROVED':'RETURNED'}}catch(e){await tx.rollback();throw e}}
